parameters.jsCode:
// Normaliza o evento da Evolution API. Nenhuma IA participa desta etapa.
// Decide tambem a rota de entrada: mensagem do cliente, mensagem do negocio ou descarte.
const LIMITE_TEXTO = 2000;
const SUFIXO_CORTE = ' [mensagem cortada]';
// Reentrega apos reconexao: acima disso a mensagem ja nao descreve o "agora"
// do cliente e responde-la parece o bot acordando de um cochilo.
const IDADE_MAXIMA_S = 1800;
// Envelopes que a Evolution usa para embrulhar a mensagem real.
const ENVELOPES = [
  'ephemeralMessage',
  'viewOnceMessage',
  'viewOnceMessageV2',
  'documentWithCaptionMessage',
];

// Origens dos servicos. Nao sao segredo (o token vai em credencial do n8n),
// mas mudam por ambiente: este e o UNICO lugar do fluxo para troca-las.
// Nao leia isto do ambiente: N8N_BLOCK_ENV_ACCESS_IN_NODE=true nesta VPS, entao
// a expressao lanca "access to env vars denied" no worker e o no morre calado.
const API_BASE = 'https://agenda-magnetica-painel.vercel.app';
const EVOLUTION_BASE = 'https://evo.fixwear.com.br';

const raiz = $input.first().json;
const body = raiz.body || raiz;
const data = body.data || {};
const chave = data.key || {};
const mensagemBruta = data.message || {};

// AUT-095: mensagem efemera, de visualizacao unica e documento com legenda vem
// dentro de um envelope. Sem desembrulhar, o conteudo real fica invisivel e
// tudo vira tipo "outro". O laco existe porque um envelope pode conter outro
// (efemera + visualizacao unica na mesma mensagem); o teto evita laco infinito
// caso a Evolution devolva uma estrutura circular.
let mensagem = mensagemBruta;
for (let volta = 0; volta < 5; volta += 1) {
  let interna = null;
  for (const nome of ENVELOPES) {
    const envelope = mensagem[nome];
    if (envelope && envelope.message) { interna = envelope.message; break; }
  }
  if (!interna) break;
  mensagem = interna;
}

const remoteJidOriginal = String(chave.remoteJid || '');
const instance = String(body.instance || '');
const msgId = String(chave.id || '');
const fromMe = chave.fromMe === true;
const evento = String(body.event || '');

// Extrai so os digitos do telefone. Descarta jid de grupo e o proprio @lid,
// que sao identificadores e nao numero discavel.
function telefoneDe(valor) {
  const texto = String(valor || '');
  if (!texto || texto.includes('@lid') || texto.includes('@g.us')) return '';
  // O sufixo apos ":" e o id do aparelho, nao faz parte do numero.
  const digitos = texto.split('@')[0].split(':')[0].replace(/\D/g, '');
  return digitos.length >= 8 ? digitos : '';
}

// AUT-094: o WhatsApp passou a entregar conversa individual com remoteJid
// "@lid". Descartar como grupo deixa cliente real sem resposta, entao usamos o
// telefone que vem junto no payload.
const ehLid = remoteJidOriginal.endsWith('@lid');
const telefone = ehLid
  ? [chave.senderPn, chave.remoteJidAlt, chave.participantPn, data.senderPn]
      .map(telefoneDe).find(Boolean) || ''
  : telefoneDe(remoteJidOriginal);
// O resto do fluxo (Evolution, Redis, cadastro) so sabe falar em @s.whatsapp.net.
const remoteJid = telefone ? `${telefone}@s.whatsapp.net` : remoteJidOriginal;
const individual = !!telefone
  && (ehLid || remoteJidOriginal.endsWith('@s.whatsapp.net'));

const texto = mensagem.conversation
  || (mensagem.extendedTextMessage && mensagem.extendedTextMessage.text)
  || (mensagem.imageMessage && mensagem.imageMessage.caption)
  || (mensagem.documentMessage && mensagem.documentMessage.caption)
  || '';

let tipo = 'outro';
let mimetype = '';
if (mensagem.audioMessage) {
  tipo = 'audio';
  mimetype = mensagem.audioMessage.mimetype || 'audio/ogg';
} else if (mensagem.imageMessage) {
  tipo = 'imagem';
  mimetype = mensagem.imageMessage.mimetype || 'image/jpeg';
} else if (String(texto).trim()) {
  tipo = 'texto';
}

// messageTimestamp chega como numero, string ou { low: N } (protobuf Long).
function segundosDe(valor) {
  if (valor && typeof valor === 'object') return segundosDe(valor.low);
  const numero = Number(valor);
  return Number.isFinite(numero) && numero > 0 ? Math.floor(numero) : 0;
}
const timestamp = segundosDe(data.messageTimestamp);
const agoraS = Math.floor(Date.parse($now.toISO()) / 1000);
// Sem timestamp confiavel a idade fica 0: nao da para descartar por suspeita.
const idadeSegundos = timestamp && Number.isFinite(agoraS) ? agoraS - timestamp : 0;

// AUT-009: a Evolution 2.3.7 reemite como messages.upsert a mensagem que o
// proprio fluxo acabou de enviar. Tratar todo fromMe como "o dono respondeu"
// faria o bot se autopausar depois de cada resposta. Quem separa os dois casos
// e o Redis, fora deste no: "Redis - envio proprio?" le am:enviada:{instance}:
// {msg_id}, que "Redis - marcar envio proprio" grava depois de cada envio.
// Chave ausente = o dono digitou de verdade, e ai a IA pausa por 30 min.

// AUT-152: reacao, figurinha e mensagem de protocolo (apagada, edicao, chave
// nova) chegam com fromMe e nao tem conteudo para atender; pausar a IA por 30
// min so porque o dono reagiu com um emoji e errado. A lista e explicita de
// proposito: video, PDF, localizacao e cartao de contato do dono sao
// intervencao humana de verdade, entao o descarte largo por tipo continua
// depois do fromMe.
const semConteudoDoDono = !!(mensagem.reactionMessage
  || mensagem.stickerMessage
  || mensagem.protocolMessage);

let rota = 'ignorar';
let motivo = '';
if (evento !== 'messages.upsert') motivo = 'evento_nao_suportado';
else if (!individual) motivo = ehLid ? 'jid_sem_telefone' : 'conversa_nao_individual';
else if (!msgId || !instance) motivo = 'evento_incompleto';
else if (fromMe && semConteudoDoDono) motivo = 'tipo_de_mensagem_nao_suportado';
// AUT-121: reentrega antiga nao vira resposta, nem quando e do proprio negocio.
else if (idadeSegundos > IDADE_MAXIMA_S) motivo = 'mensagem_antiga';
else if (fromMe) { rota = 'humano'; motivo = 'mensagem_enviada_pelo_negocio'; }
else if (tipo === 'outro') motivo = 'tipo_de_mensagem_nao_suportado';
else rota = 'cliente';

// AUT-165: cortar em silencio faz o cliente achar que foi lido por inteiro.
const textoCompleto = String(texto);
const conteudo = textoCompleto.length > LIMITE_TEXTO
  ? textoCompleto.slice(0, LIMITE_TEXTO) + SUFIXO_CORTE
  : textoCompleto;

return [{
  json: {
    rota_entrada: rota,
    motivo,
    instance,
    remote_jid: remoteJid,
    remote_jid_original: remoteJidOriginal,
    telefone,
    msg_id: msgId,
    from_me: fromMe,
    evento,
    tipo,
    conteudo,
    base64: String(mensagem.base64 || mensagemBruta.base64 || data.base64 || ''),
    mimetype,
    push_name: String(data.pushName || '').slice(0, 60),
    timestamp,
    idade_segundos: idadeSegundos,
    api_base: API_BASE.replace(/\/$/, ''),
    evolution_base: EVOLUTION_BASE.replace(/\/$/, ''),
  },
}];

// Agrupa mensagens proximas do mesmo contato. So a execucao da ultima mensagem
// do buffer segue adiante; as anteriores encerram sem resposta.
const JANELA_BUFFER_S = 60;
const LIMITE_TEXTO = 4000;
const SUFIXO_CORTE = ' [mensagem cortada]';

const entrada = $('normalizar entrada').first().json;
const bruto = $input.first().json.buffer;

// A chave e `set` com TTL, entao o que chega e a string do ARRAY inteiro -
// `montar buffer` grava `JSON.stringify(lista)`. Tratar essa string como um
// item so deixava o agrupamento morto em silencio: o parse devolvia um array,
// que nao tem `msg_id`, entao a lista efetiva ficava vazia e cada balao da
// rajada virava uma resposta.
// As duas outras formas continuam aceitas: array de verdade (se algum dia a
// chave voltar a ser lista) e string de um objeto so (buffer gravado por versao
// antiga do fluxo, que nao pode parar de funcionar no meio de uma conversa).
let lista = [];
if (Array.isArray(bruto)) {
  lista = bruto;
} else if (typeof bruto === 'string' && bruto) {
  try {
    const lido = JSON.parse(bruto);
    lista = Array.isArray(lido) ? lido : [lido];
  } catch (e) {
    lista = [bruto];
  }
}

// AUT-012: se a execucao morrer entre gravar e apagar, o buffer orfao sobrevive
// ate o TTL e reapareceria na proxima conversa, misturando o assunto de ontem
// com o de hoje. O TTL de 300 s (em `Redis - juntar mensagem`) e quem apaga de
// fato; este filtro e a segunda linha, para o orfao que ainda esta vivo.
const atualS = Number(entrada.timestamp || 0);
// Sem timestamp na mensagem atual o relogio do fluxo e a unica referencia:
// aceitar tudo faria o orfao entrar como se fosse a conversa de agora.
const relogioS = Math.floor(Date.parse($now.toISO()) / 1000);
const agora = atualS || (Number.isFinite(relogioS) ? relogioS : 0);
const dentroDaJanela = (item) => {
  const quando = Number(item.timestamp || 0);
  // Item sem hora e orfao de idade desconhecida quando a mensagem atual tem
  // timestamp confiavel. So entra quando a atual tambem nao tem: buffer gravado
  // por versao antiga do fluxo nao pode parar de funcionar.
  if (!quando) return !atualS;
  if (!agora) return true;
  return Math.abs(quando - agora) <= JANELA_BUFFER_S;
};

const itens = lista
  .map((x) => {
    if (x && typeof x === 'object') return x;
    try { return JSON.parse(x); } catch (e) { return null; }
  })
  .filter((x) => x && x.msg_id)
  .filter(dentroDaJanela);

// Buffer perdido (expiracao/reinicio do Redis): usa somente a mensagem atual.
const efetivos = itens.length ? itens : [entrada];
const ultimo = efetivos[efetivos.length - 1];

if (ultimo.msg_id !== entrada.msg_id) {
  return [{ json: { processar: false, motivo: 'mensagem_mais_recente_assume' } }];
}

const textos = efetivos.map((i) => String(i.conteudo || '').trim()).filter(Boolean);
const midia = [...efetivos].reverse().find((i) => i.tipo === 'audio' || i.tipo === 'imagem') || null;

// AUT-165: mesmo criterio de `normalizar entrada`, agora sobre o texto juntado.
const juntado = textos.join('\n');
const conteudo = juntado.length > LIMITE_TEXTO
  ? juntado.slice(0, LIMITE_TEXTO) + SUFIXO_CORTE
  : juntado;

return [{
  json: {
    processar: true,
    motivo: 'ultima_mensagem_do_buffer',
    quantidade: efetivos.length,
    tipo: midia ? midia.tipo : 'texto',
    conteudo,
    // O id da midia, que nao e o da ultima mensagem quando o cliente manda um
    // audio e complementa com texto: "buscar audio"/"buscar imagem" pedem o
    // arquivo por este id e a Evolution devolve 400 se receber o id do texto.
    midia_msg_id: midia ? String(midia.msg_id || '') : '',
    base64: midia ? String(midia.base64 || '') : '',
    mimetype: midia ? String(midia.mimetype || '') : '',
  },
}];

// Fim do atendimento quando /api/ai/contexto respondeu `ok: false`.
// Nem todo `ok: false` e igual: RECUSA_DE_NEGOCIO e a empresa dizendo nao
// (atendimento desligado, instancia de outro produto, cadastro incompleto) e
// encerrar calado e o comportamento certo. Qualquer outro codigo — ou resposta
// sem envelope — e a integracao quebrada, e ai o silencio e o pior resultado
// possivel: o cliente fica sem resposta e ninguem fica sabendo, porque
// `saveDataSuccessExecution: none` nao guarda execucao que terminou bem.
const RECUSA_DE_NEGOCIO = [
  'AUTOMACAO_DESATIVADA',      // o dono desligou o atendimento no painel
  'INSTANCIA_DESCONHECIDA',    // a instancia nao pertence a este produto
  'EMPRESA_NAO_CONFIGURADA',   // onboarding incompleto
];

const erro = ($input.first().json || {}).error || {};
const codigo = String(erro.code || '');

if (!RECUSA_DE_NEGOCIO.includes(codigo)) {
  // Mensagem so com o codigo: `message` da API e seguro, mas nao ha motivo
  // para copiar corpo de resposta para dentro do log de execucao.
  throw new Error(
    'contexto indisponivel por falha, nao por regra: ' +
    (codigo || 'resposta sem envelope') +
    '. Confira AUTOMATION_API_TOKEN nas variaveis do projeto na Vercel e a ' +
    'credencial "Agenda Magnetica - token da automacao" no n8n.'
  );
}

return [{ json: { encerrado_por: codigo } }];

// Monta o contexto minimo enviado a IA. Tudo vem de uma unica chamada a
// /api/ai/contexto: a empresa e derivada da instancia no servidor, o cliente e
// localizado ou criado dentro dela e o catalogo e o dela. Nenhum id de empresa
// ou de cliente circula por aqui: as rotas da API nao aceitam esses parametros.
const HISTORICO_MAX = 6;
const FUSO_PADRAO = 'America/Sao_Paulo';
const OFFSET_MIN = -180; // America/Sao_Paulo nao usa horario de verao desde 2019.

const entrada = $('normalizar entrada').first().json;
const conteudoItem = $('conteudo do cliente').first().json;
const envelope = $('contexto da empresa').first().json || {};
const chaves = $input.first().json;

// Sem envelope valido nao existe contexto. O fluxo nao completa empresa nem
// cliente por conta propria: quem nao tem contexto vai para uma pessoa.
const dados = (envelope.ok === true && envelope.data) ? envelope.data : {};
const empresaApi = dados.empresa || {};
const clienteApi = dados.cliente || {};

function texto(v) { return v === null || v === undefined ? '' : String(v); }
function numero(v) { const n = Number(v); return Number.isFinite(n) ? n : null; }
function lista(v) { return Array.isArray(v) ? v : []; }

// Nome de exibicao: push name do WhatsApp costuma trazer nome de empresa, apelido
// ou emoji. So usamos quando parece um primeiro nome de pessoa.
// Casa por palavra inteira, sobre o nome sem acento. Como substring solta,
// 'mei' derrubava "Rosimeire" e "Meireles", e 'me ' derrubava "Guilherme
// Alves" e "Jaime Souza" - todos nomes de gente.
const MARCAS_DE_NEGOCIO = /\b(ltda|mei|me|studio|estudio|salao|clinica|consultorio|espaco|barbearia|atelier|atelie|center|centro|servicos|com\.br|www|oficial|delivery)\b/;

function semAcento(s) { return s.normalize('NFD').replace(/[\u0300-\u036f]/g, ''); }

// Texto que o assinante escreve sobre o negocio, no painel, e que vai para
// dentro do system prompt. Mesmo tratamento do historico, e pela mesma razao:
// sem < > o texto nao fecha o delimitador <negocio>, sem invisiveis e bidi nao
// esconde instrucao no meio da linha, e sem rotulo de papel nao forja um turno.
// Aqui a limpeza e na RENDERIZACAO, nao na gravacao: quem grava e o painel, e
// devolver o texto mutilado no formulario seria pior do que limpar na saida.
// A quebra de linha sobrevive de proposito - o campo pede uma informacao por
// linha, e amassar tudo numa linha so piora a leitura do modelo.
const NEGOCIO_MAX = 2000; // igual a LIMITE_DESCRICAO em services/api/server.py.
const CAMPO_MAX = 300; // nome, telefone, email e endereco: o teto de verdade e da API.
// U+2800, U+180E e U+3164 entram porque sao espaco de mentira: nao casam `\s` e
// nao sao invisiveis classicos, entao "assistente<U+2800>:" atravessava a
// neutralizacao de rotulo intacto.
const INVISIVEIS = new RegExp('[\\u0085\\u00ad\\u180e\\u200b-\\u200f\\u202a-\\u202e\\u2060\\u2066-\\u2069\\u2800\\u3164\\ufeff]', 'g');
// Limpeza de caractere, para TODO campo da empresa que entra no system prompt.
// Nao e so a descricao que pode fechar o delimitador: nome, telefone, email e
// endereco vao para o mesmo prompt, e o fechamento escrito no endereco
// contornava a protecao do campo do lado.
function semEstrutura(bruto) {
  return texto(bruto)
    // Aspa angular no lugar de apagar: `<` virando espaco transformava "atendo
    // a partir de <12 anos" em "12 anos", que diz o contrario. Estas nao fecham
    // o delimitador e nao mentem.
    .replace(/[<\uFF1C]/g, '\u2039')
    .replace(/[>\uFF1E]/g, '\u203A')
    .replace(INVISIVEIS, '')
    .replace(/[\uFF1A\uFE55\u2236\u02D0]/g, ':')
    .replace(/\b(assistente|sistema|cliente|usuario|usu\u00e1rio|assistant|system|user|bot|atendente|ia)\s*:/gi, '$1 -')
    .replace(/[^\S\n]+/g, ' ')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}
function campoCurto(bruto) {
  return semEstrutura(bruto).replace(/\n+/g, ' ').slice(0, CAMPO_MAX);
}
function paraPrompt(bruto) {
  const limpo = semEstrutura(bruto)
    .slice(0, NEGOCIO_MAX)
    // Corte no meio de um par surrogate deixa meia letra, que vira caractere
    // invalido no prompt. Tira a metade solta em vez de emitir lixo.
    .replace(/[\uD800-\uDBFF]$/, '');
  if (!limpo) return '';
  // Cada linha marcada. Mata de uma vez cabecalho ("# Regras"), cerca de
  // codigo, separador ("---") e numeracao de regra, sem depender de uma lista
  // de padroes que alguem teria de manter: o texto do dono deixa de conseguir
  // MONTAR uma secao com a cara das nossas.
  return limpo.split('\n').map((linha) => `| ${linha}`).join('\n');
}

function primeiroNomeConfiavel(nome) {
  const limpo = texto(nome).trim();
  if (!limpo) return '';
  const comparavel = semAcento(limpo.toLowerCase());
  if (MARCAS_DE_NEGOCIO.test(comparavel)) return '';
  if (/\d/.test(limpo)) return '';
  const primeiro = limpo.split(/\s+/)[0];
  if (primeiro.length < 2 || primeiro.length > 20) return '';
  if (!/^[A-Za-zÀ-ÿ'’-]+$/.test(primeiro)) return '';
  return primeiro.charAt(0).toUpperCase() + primeiro.slice(1).toLowerCase();
}

const agora = new Date();
const agoraLocal = new Date(agora.getTime() + OFFSET_MIN * 60000);

const servicos = lista(dados.procedimentos)
  .map((p) => ({
    id: numero(p.id),
    nome: texto(p.nome),
    valor: numero(p.valor),
    duracao_minutos: numero(p.duracao_minutos) || 60,
    // agendavel: false = nenhum profissional ativo executa o servico. Ele tem
    // preco para responder uma duvida, mas nunca teria horario livre.
    agendavel: p.agendavel !== false,
  }))
  .filter((p) => p.id && p.nome);

const profissionais = lista(dados.profissionais)
  .map((p) => ({ id: numero(p.id), nome: texto(p.nome), area: texto(p.area) }))
  .filter((p) => p.id && p.nome);

const horarios = lista(empresaApi.horarios)
  .map((h) => ({
    dia_semana: numero(h.dia_semana),
    hora_inicio: texto(h.hora_inicio),
    hora_fim: texto(h.hora_fim),
  }))
  .filter((h) => h.dia_semana !== null);

let pendente = null;
try {
  const cru = chaves.pendente;
  const obj = typeof cru === 'string' ? JSON.parse(cru) : cru;
  // Sem acao_id a chave_idempotencia sai vazia, a API recusa com 422 e a
  // conversa e transferida. Pendencia sem chave nao vale: melhor reabrir.
  if (obj && obj.tipo && typeof obj.acao_id === 'string' && obj.acao_id.length >= 8) pendente = obj;
} catch (e) { pendente = null; }

let estado = { historico: [], slots_oferecidos: [], consultas_candidatas: [], reagendar_consulta_id: null };
try {
  const cru = chaves.estado;
  const obj = typeof cru === 'string' ? JSON.parse(cru) : cru;
  if (obj && typeof obj === 'object') estado = Object.assign(estado, obj);
} catch (e) { /* estado ausente e um caso normal */ }

const nomeCliente = texto(clienteApi.nome) || entrada.push_name;
// O telefone normalizado pela API e a identidade do cliente nas proximas
// chamadas. Sem ele nao ha operacao possivel, e o fluxo transfere.
const telefoneCliente = texto(clienteApi.telefone);
const temContexto = Boolean(dados.empresa && telefoneCliente);

return [{
  json: {
    tem_contexto: temContexto,
    erro_contexto: temContexto ? null : texto((envelope.error || {}).code) || 'sem_envelope',
    agora_iso: agora.toISOString(),
    agora_local: agoraLocal.toISOString().replace('Z', '-03:00'),
    fuso: texto(empresaApi.fuso) || FUSO_PADRAO,
    empresa: {
      nome: campoCurto(empresaApi.nome) || 'nosso atendimento',
      telefone: campoCurto(empresaApi.telefone),
      email: campoCurto(empresaApi.email),
      endereco: campoCurto(empresaApi.endereco),
      // Unica fonte do que nao cabe no catalogo: forma de pagamento, convenio,
      // estacionamento, o que levar na primeira sessao. Vazio fica vazio - o
      // prompt escreve 'nada cadastrado' e a regra 3 faz o resto.
      descricao: paraPrompt(empresaApi.descricao),
      assistente_nome: texto(empresaApi.assistente_nome) || 'assistente virtual',
      assistente_tom: texto(empresaApi.assistente_tom) || 'cordial, direto e simples',
      exige_profissional: empresaApi.exige_profissional === true,
    },
    servicos,
    profissionais,
    horarios,
    cliente: {
      nome: nomeCliente,
      primeiro_nome: primeiroNomeConfiavel(nomeCliente),
      telefone: telefoneCliente,
      novo: clienteApi.novo === true,
      tem_cadastro_confirmado: Boolean(texto(clienteApi.nome)),
    },
    pendente,
    estado: {
      historico: Array.isArray(estado.historico) ? estado.historico.slice(-HISTORICO_MAX) : [],
      slots_oferecidos: Array.isArray(estado.slots_oferecidos) ? estado.slots_oferecidos : [],
      consultas_candidatas: Array.isArray(estado.consultas_candidatas) ? estado.consultas_candidatas : [],
      reagendar_consulta_id: numero(estado.reagendar_consulta_id),
      // Inicio da pendencia que o ultimo turno realmente anunciou, gravado por
      // 'montar resposta'. Este objeto tem forma fixa, entao a chave precisa
      // estar aqui: sem ela 'resolver e decidir' leria sempre undefined e a
      // pendencia nunca seria comparavel - ou nenhum "sim" fecharia horario, ou
      // o "sim" fecharia um horario que o turno anterior nem mencionou. Ausente
      // no Redis vira null, que e o valor de "o ultimo turno nao falou de
      // pendencia nenhuma".
      pendente_falada: texto(estado.pendente_falada) || null,
      // Servico citado no ultimo turno, gravado por 'montar resposta'. Mesma
      // razao da linha acima: forma fixa, entao a chave precisa existir aqui ou
      // o servico morre a cada turno e o fluxo repergunta o que ja foi dito.
      // So sobrevive com id numerico e nome: registro pela metade nao serve de
      // memoria e viraria busca com id vazio.
      servico_ultimo: (estado.servico_ultimo && numero(estado.servico_ultimo.id)
        && texto(estado.servico_ultimo.nome))
        ? {
          id: numero(estado.servico_ultimo.id),
          nome: texto(estado.servico_ultimo.nome),
          duracao_minutos: numero(estado.servico_ultimo.duracao_minutos),
        }
        : null,
      // Data, periodo e hora que o ultimo turno pediu, gravados por 'montar
      // resposta'. Mesma razao das duas linhas acima: forma fixa, entao a chave
      // precisa existir aqui. Sem ela, "quero corte e barba amanha as 10h"
      // seguido de "corte" perdia o dia e a hora e virava busca de 14 dias.
      // So sobrevive com pelo menos um dos tres campos preenchido: registro
      // vazio nao e memoria e so atrapalharia a leitura do turno seguinte.
      data_ultima: (estado.data_ultima
        && (texto(estado.data_ultima.date_text)
          || texto(estado.data_ultima.period)
          || texto(estado.data_ultima.time_text)))
        ? {
          date_text: texto(estado.data_ultima.date_text) || null,
          period: texto(estado.data_ultima.period) || null,
          time_text: texto(estado.data_ultima.time_text) || null,
        }
        : null,
    },
    conteudo: texto(conteudoItem.conteudo),
    tipo_entrada: texto(conteudoItem.tipo) || 'texto',
    entrada_incerta: conteudoItem.entrada_incerta === true,
    msg_id: entrada.msg_id,
    instance: entrada.instance,
    remote_jid: entrada.remote_jid,
