// Valida a saida da IA fora da IA. Nada aqui confia no modelo: enum fechado,
// tipos coeridos, ids internos descartados e next_action recalculado.
const INTENCOES = [
  'saudacao', 'faq', 'consultar_disponibilidade', 'preparar_agendamento',
  'confirmar_acao', 'recusar_acao', 'consultar_agendamento', 'preparar_reagendamento',
  'preparar_cancelamento', 'atualizar_cadastro', 'falar_com_humano', 'fora_do_escopo',
];
const ACOES = [
  'answer', 'ask_clarification', 'check_availability', 'confirm_pending',
  'discard_pending', 'list_appointments', 'update_customer', 'handoff',
];
// next_action e sempre derivada da intencao pelo sistema; o campo da IA e ignorado.
const ACAO_POR_INTENCAO = {
  saudacao: 'answer',
  faq: 'answer',
  fora_do_escopo: 'answer',
  consultar_disponibilidade: 'check_availability',
  preparar_agendamento: 'check_availability',
  confirmar_acao: 'confirm_pending',
  recusar_acao: 'discard_pending',
  consultar_agendamento: 'list_appointments',
  preparar_reagendamento: 'list_appointments',
  preparar_cancelamento: 'list_appointments',
  atualizar_cadastro: 'update_customer',
  falar_com_humano: 'handoff',
};
const PERIODOS = ['manha', 'tarde', 'noite'];
// O motivo da transferencia e gravado no Redis e decide o TTL da pausa. Texto
// livre do modelo nunca casaria com a lista de motivos e ainda arrastaria
// trecho da mensagem do cliente para dentro do registro: enum fechado.
// `crise` entra como segunda linha: quando a regex perde a forma escrita (erro
// de digitacao, outra lingua, giria), o enum fechado descartava o unico aviso
// que sobrava e o cliente recebia "Claro. Vou parar por aqui" sem o 188. O
// modelo so pode PEDIR a rota de crise; quem a executa continua sendo a guarda
// deterministica. `pedido_do_titular` fica de fora de proposito: e um direito
// com registro proprio, e a IA nao decide quando alguem exerceu.
const RAZOES_HANDOFF = ['pedido_do_cliente', 'reclamacao', 'cobranca', 'assunto_sensivel', 'crise', 'nao_entendi'];
const CAMPOS_CADASTRO = ['nome', 'email', 'data_nascimento', 'interesses'];

const bruto = $input.first().json || {};

// Timeout, 5xx ou cota da OpenAI chegam aqui como item de erro do no anterior.
// Isso e falha de infraestrutura, nao modelo devolvendo bobagem: precisa de
// motivo proprio para poder ser retentado em vez de transferir e pausar a IA.
if (bruto.error !== undefined && bruto.error !== null) {
  return [{ json: { valida: false, motivo: 'falha_ia', interp: null } }];
}

let saida = bruto.output !== undefined ? bruto.output : bruto;
if (typeof saida === 'string') {
  const limpo = saida.replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
  try { saida = JSON.parse(limpo); } catch (e) { saida = null; }
}

if (!saida || typeof saida !== 'object') {
  return [{ json: { valida: false, motivo: 'saida_nao_estruturada', interp: null } }];
}

function texto(v) {
  if (v === null || v === undefined) return null;
  const s = String(v).trim();
  return s && s.toLowerCase() !== 'null' ? s.slice(0, 200) : null;
}

const intencao = INTENCOES.includes(saida.intent) ? saida.intent : null;
if (!intencao) {
  return [{ json: { valida: false, motivo: 'intencao_fora_do_enum', interp: null } }];
}

let confianca = Number(saida.confidence);
if (!Number.isFinite(confianca)) confianca = 0;
confianca = Math.min(1, Math.max(0, confianca));

const ent = (saida.entities && typeof saida.entities === 'object') ? saida.entities : {};
const atualizacoesBrutas = (ent.customer_updates && typeof ent.customer_updates === 'object') ? ent.customer_updates : {};
const atualizacoes = {};
for (const campo of CAMPOS_CADASTRO) {
  const valor = texto(atualizacoesBrutas[campo]);
  if (valor) atualizacoes[campo] = valor;
}

const periodo = PERIODOS.includes(ent.period) ? ent.period : null;
const acaoIA = ACOES.includes(saida.next_action) ? saida.next_action : null;

const interp = {
  version: '1.0',
  intent: intencao,
  confidence: confianca,
  entities: {
    service_query: texto(ent.service_query),
    professional_query: texto(ent.professional_query),
    date_text: texto(ent.date_text),
    time_text: texto(ent.time_text),
    period: periodo,
    appointment_hint: texto(ent.appointment_hint),
    customer_updates: atualizacoes,
  },
  next_action: ACAO_POR_INTENCAO[intencao],
  next_action_ia: acaoIA,
  requires_confirmation: saida.requires_confirmation === true,
  requires_human: saida.requires_human === true,
  handoff_reason: RAZOES_HANDOFF.includes(saida.handoff_reason) ? saida.handoff_reason : null,
  reply: String(saida.reply === null || saida.reply === undefined ? '' : saida.reply).slice(0, 700),
};

return [{ json: { valida: true, motivo: 'ok', interp } }];

// Regras deterministicas do atendimento. A IA nao escolhe id, data, rota,
// filtro, ferramenta nem resultado: tudo e resolvido aqui. As chamadas de
// agenda saem prontas daqui (caminho e corpo), para que a repeticao de uma
// escrita use exatamente o mesmo pedido, com a mesma chave de idempotencia.
const LIMIAR_PADRAO = 0.75;      // ajuste unico para pedir esclarecimento
const LIMIAR_DESTRUTIVO = 0.85;  // cancelar / reagendar / confirmar
const JANELA_PADRAO_DIAS = 14;
const PASSO_MINUTOS = 30;
const LIMITE_SLOTS = 50;         // teto aceito pelo contrato; ofertamos 2
const JANELA_MAXIMA_DIAS = 30;   // limite de /api/ai/disponibilidade
// Ninguem sai de casa em 3 minutos. O no 'avaliar horarios' descarta slot que
// comece antes disso; a busca usa o mesmo piso para nao pedir o que sera
// jogado fora e nao oferecer horario que "acabou de ser ocupado" no sim.
const ANTECEDENCIA_MIN = 60;
// Recorte em volta da hora pedida. Sem ele a janela do dia inteiro estourava o
// limite de slots antes do meio-dia e quem pediu 16h ouvia duas opcoes da
// manha. A margem deixa alternativa perto quando a hora exata esta ocupada.
const MARGEM_HORA_MIN = 120;
const OFFSET_MIN = -180; // America/Sao_Paulo, sem horario de verao desde 2019

// Fallback de quem nao tem expediente cadastrado; com horarios na empresa a
// janela sai de ctx.horarios.
const DIA_INICIO = 7;
const DIA_FIM = 21;
const PERIODOS = { manha: [DIA_INICIO, 12], tarde: [12, 18], noite: [18, 21] };

// Lista por substring casava "vendedor" e "doida" e perdia "estou com dor".
// Fronteira de palavra resolve os dois lados com uma expressao so.
const RE_SENSIVEL = new RegExp('\\b(?:'
  + 'dor|dores|doi|doer|doendo|sangr\\w*|infec\\w*|febre|pus|inflam\\w*|alergi\\w*'
  + '|remedio|remedios|pomada|pomadas|antibiotic\\w*|diagnostic\\w*|diabet\\w*'
  + '|cancer|tumor|tumores|ferida|feridas|machuc\\w*|machuqu\\w*|lesao|lesoes|medicament\\w*'
  // pele e pe
  + '|mancha|manchas|coceira|verruga|verrugas|micose|unha encravada|herpes|calo|calos'
  // tatuagem
  + '|hepatite|hiv'
  // fisioterapia
  + '|fratura|fraturas|entorse|hernia|ciatico|ciatica|tendinite'
  // nutricao
  + '|dieta restritiva|bariatrica|bariatrico'
  // documentos
  + '|laudo|laudos|atestado|atestados|receita|receitas'
  + ')\\b');
// A papelada esta em RE_SENSIVEL porque a IA nao pode OPINAR sobre laudo
// ("esse laudo ja serve, pode vir sem"), e sai so do exame do TEXTO DO MODELO:
// o campo "Sobre o negocio" pede "o que levar na primeira sessao", o dono
// escreve "traga exames e o laudo do medico", e engolir isso era engolir a
// resposta que veio do proprio cadastro.
const RE_PAPELADA = /\b(?:laudos?|atestados?|receitas?)\b/g;

// Contraindicacao nao depende de pergunta, mas depende do caminho: "quero
// drenagem, estou gravida" precisa de pessoa antes da oferta de horario.
const RE_CONDICAO = /\b(?:gestante\w*|gravid\w*|amamentando|anticoagul\w*|marca[ -]?passo|trombose|quimio|quimioterapia|pos[ -]?operatorio)\b/;
// Sem estes dois filtros a guarda virou incondicional: a resposta NEGATIVA a
// pergunta de triagem ("nao estou gravida, pode marcar") transferia de novo,
// em laco com a pessoa que acabou de perguntar, e a condicao de outra pessoa
// ("minha irma esta gravida, quero dar um presente") tirava a conversa da IA.
const RE_CONDICAO_NEGADA = /\bnao (?:estou|sou|uso|tomo|fiz|fui|tenho)\b/;
const RE_CONDICAO_TERCEIRO = /\bminha (?:mae|irma|amiga|filha|prima|avo|tia|sogra|esposa|cunhada|vizinha)\b|\bmeu (?:pai|irmao|filho|primo|marido|namorado|sogro|amigo)\b/;
// So estes caminhos ofertam horario. Em cancelamento, confirmacao de pendencia
// e FAQ a mesma palavra nao contraindica nada: bloquear ali tirou da cliente
// gravida ate o direito de desmarcar pelo bot.
// Desmarcar e confirmar sao os dois caminhos que a contraindicacao nao pode
// bloquear: a gestante precisa conseguir cancelar o horario dela sem cair numa
