const INTENTS_SEM_CONDICAO = ['preparar_cancelamento', 'confirmar_acao', 'recusar_acao'];

// Crise vem antes de tudo: nada de agenda, nada de resposta gerada pela IA.
// Os termos isolados que tambem tem uso banal em salao sairam: "apanhei" e
// "peguei" em pt-BR, "ameaca de chuva" e "abuso de sol" nao sao crise, e cada
// um deles mandava o CVV para quem so queria remarcar. Em troca entram as
// formas correntes da fala: sem elas "nao quero mais viver" caia no handoff
// generico ("melhor uma pessoa te responder com calma"), sem CVV.
// "automutila\w*" nao cobria "me automutilei"; o radical curto cobre.
const RE_CRISE = new RegExp('\\b(?:'
  + 'suicid\\w*|me matar|me mate|tirar a (?:minha |propria )?vida|automutil\\w*|overdose'
  // Fronteira com Uruguai e Argentina: as duas formas mais correntes.
  + '|matarme|quiero morir'
  // Em pt-BR a ideacao sai por "morrer"/"viver", nao por "me matar" - a forma
  // que estava so em RE_AUTOLESAO_SINAL, regex que nunca e consultada sozinha.
  // O veto de hiperbole existe porque "morrer de rir", "morrer de fome" e
  // "cansei de viver correndo" sao fala comum e nao sao pedido de socorro.
  + '|(?:quero|queria|penso em|pensando em|vontade de|melhor(?: eu)?)\\s+morrer(?!\\s+de\\s|\\s+de tanto)'
  + '|queria estar mort\\w*|nao vejo sentido em viver'
  // "vive\\w*" cobre o erro de digitacao corrente ("nao quero mais viveer").
  + '|nao quero (?:mais )?vive\\w*|nao aguento mais viver'
  + '|cansei de viver(?!\\s+(?:correndo|assim|desse jeito))'
  + '|acabar com tudo'
  + '|dar um fim (?:nisso|em tudo|na (?:minha )?vida)|dar fim na vida'
  // "quero sumir com essa mancha" e pedido de estetica, nao de socorro.
  + '|quero sumir(?!\\s+com\\b)|quero desaparecer(?!\\s+com\\b)'
  // "violencia" solto disparava em noticia, filme e desabafo sobre o bairro:
  // o termo precisa de quem sofre, como "agressao" e "abuso" ja exigiam.
  + '|sofri violencia|sofrendo violencia|vitima de violencia|violencia domestica'
  + '|sofri agressao|fui agredid\\w*|agressao domestica'
  + '|me bateu|me bate|me agrediu'
  // "apanhei do meu marido" e a forma mais frequente de relatar agressao
  // domestica; o complemento obrigatorio nao reabre "apanhei um resfriado".
  + '|apanh(?:ei|o|ando) d(?:o|a|e) (?:meu|minha|ele|ela|marido|namorado|pai|padrasto)'
  + '|apanhei em casa'
  // "abusad\\w*" sozinho e girio de caro e de elogio no RS ("preco abusado",
  // "abusado de bom", "guri abusado") e mandava o CVV para quem falou de preco.
  + '|abuso sexual|fui abusad\\w*|foi abusad\\w*|abusad\\w* sexualmente'
  + '|sofri abuso|abusou de mim|vitima de abuso'
  + '|me ameac\\w*|ameaca de morte'
  + ')\\b');
// "me cortar"/"me cortei" e ambiguo dentro de um salao. Crescer a lista de
// excecoes esteticas nao fecha (cuticula, pele e depilacao nunca cabem), entao
// autolesao exige um sinal de sofrimento ou de repeticao por perto.
// "machuc" + "ei" gera "machucei", forma que nao existe em portugues: o
// preterito real e "machuquei", e era justamente o relato do que ja aconteceu
// que nunca disparava.
const RE_AUTOLESAO = /\bme cort(?:ar|ei|o|ando)\b|\bme machuc(?:ar|ando|o)\b|\bme machuquei\b|\bme fer(?:i|ir|indo|e)\b/;
// Sinal forte: nao ha leitura estetica possivel. Vence o veto de RE_CORTE_ESTETICO,
// porque o bloco agrupado do WhatsApp mistura pedido de horario com desabafo e
// "quero cortar o cabelo. ontem me cortei de proposito no pulso" e o caso de risco.
const RE_AUTOLESAO_SINAL_FORTE = /\bde proposito\b|\bpulso\b|\bpunho\b|\bde raiva\b|pra aliviar|nao consigo parar|quero morrer|vontade de morrer|me odeio/;
// Sinal fraco: indica, nao prova. "sozinho", "braco" e "coxa" sairam porque sao
// rotina de depilacao e barba - "me cortei no braco com a pinca" virava crise.
const RE_AUTOLESAO_SINAL = /\bde novo\b|nao aguento|nao consigo mais|sofr\w*|deprim\w*|desesper\w*|triste/;
const RE_CORTE_ESTETICO = /\b(?:cabelo|cabelos|barba|bigode|franja|unha|unhas|cuticula|cuticulas|ponta|pontas|sobrancelha\w*|depil\w*|pelo|pelos|cera|lamina|gilete|pinca|tesoura)\b/;

// Direito do titular: apagar dados ou sair da lista sai da IA e vai para pessoa.
// Verbo e objeto agora precisam estar colados. Testados soltos na mensagem
// inteira ("apag|exclu|remov|delet" em qualquer lugar E "dado|cadastro|conta"
// em qualquer outro), "pode remover o Rafael do meu registro?" e "quero remover
