// "seu pedido vai ser tratado" - resposta sem sentido para quem so ajustava
// preferencia, e conversa perdida para o negocio.
// Um determinante so nao cobre a fala real, que empilha artigo e possessivo
// ("o meu cadastro", "todos os meus dados"): a repeticao limitada fecha o
// pedido escrito por extenso sem soltar o verbo do objeto.
const RE_TITULAR_APAGAR = new RegExp(
  '\\b(?:apag|exclu|remov|delet)\\w*\\s+'
  + '(?:(?:o|a|os|as|meu|minha|meus|minhas|todos|todas|esse|essa|esses|essas)\\s+){0,3}'
  + '(?:dado|dados|cadastro|conta|registro)s?\\b'
  + '|borrar mis datos|eliminar mis datos|direito de (?:exclusao|eliminacao)',
);
// O opt-out tambem exige objeto de comunicacao. Sem ele "nao quero mais receber
// massagem com o Rafael, prefiro a Paula" e "para de me mandar as 8, me manda as
// 10" eram lidas como descadastro. Ate duas palavras entre o verbo e o objeto
// cobrem artigo e possessivo ("nao me manda mais o seu lembrete").
const RE_TITULAR_OPTOUT = new RegExp(
  '(?:(?:nao quero mais(?: receber)?|nao me mand\\w* mais|para de (?:me )?mandar|nao manda mais)'
  + '\\s+(?:\\w+\\s+){0,2}?(?:mensage\\w*|lembrete\\w*|promo\\w*|propaganda\\w*|whatsapp|zap|nada)\\b)'
  + '|me tir\\w* d(?:a|essa|esta) lista|descadastr\\w*',
);
// Qualificador restritivo denuncia ajuste de preferencia, nao descadastro:
// "nao me manda mais o lembrete de manha, so a tarde" pedia outro horario e
// recebia transferencia com 12h de IA pausada.
const RE_OPTOUT_RESTRITO = /\b(?:so|apenas|prefiro|melhor|antes|depois)\b|\bde manha\b|\bde tarde\b|\bas \d/;

const TITULOS = ['dr', 'dra', 'doutor', 'doutora', 'prof', 'profa', 'sr', 'sra'];

const ctx = $('montar contexto').first().json;
const validacao = $input.first().json;

function normalizar(s) {
  return String(s === null || s === undefined ? '' : s)
    .toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9\s/:-]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function pad(n) { return String(n).padStart(2, '0'); }
function partesLocais(iso) {
  const d = new Date(new Date(iso).getTime() + OFFSET_MIN * 60000);
  return {
    ano: d.getUTCFullYear(), mes: d.getUTCMonth() + 1, dia: d.getUTCDate(),
    hora: d.getUTCHours(), min: d.getUTCMinutes(), dow: d.getUTCDay(),
  };
}
function isoLocal(p, hora, min) {
  return `${p.ano}-${pad(p.mes)}-${pad(p.dia)}T${pad(hora)}:${pad(min)}:00-03:00`;
}
// resolverData devolve dia sem `dow` no caminho de data numerica: o dia da
// semana e recalculado aqui para nao depender de quem montou o objeto.
function dowDe(p) { return new Date(Date.UTC(p.ano, p.mes - 1, p.dia)).getUTCDay(); }
function isoMin(p, minutos) {
  const m = Math.max(0, Math.min(23 * 60 + 59, Math.round(minutos)));
  return isoLocal(p, Math.floor(m / 60), m % 60);
}
function somarDias(p, n) {
  const d = new Date(Date.UTC(p.ano, p.mes - 1, p.dia));
  d.setUTCDate(d.getUTCDate() + n);
  return { ano: d.getUTCFullYear(), mes: d.getUTCMonth() + 1, dia: d.getUTCDate(), dow: d.getUTCDay() };
}

// Ofuscacao com numero no meio da palavra ("quero me m4tar") passava direto
// pelas guardas. O colapso vale so para o texto das guardas: aplicado ao texto
// de data e hora, "as 14h" viraria "as iah" e o agendamento quebrava.
function colapsarLeet(s) {
  return s.replace(/0/g, 'o').replace(/1/g, 'i').replace(/3/g, 'e').replace(/4/g, 'a').replace(/5/g, 's');
}
// Separador dentro da palavra ("quero me ma@tar", "q.u.e.r.o. m.e. m.a.t.a.r")
// passava limpo: normalizar troca o separador por espaco e a palavra some. Roda
// antes de normalizar, sobre o texto bruto, e so para o texto das guardas -
// aplicado a data e hora, "20/08" e "as 14h" quebrariam o agendamento.
function juntarLetrasSeparadas(s) {
  return String(s === null || s === undefined ? '' : s)
    .replace(/(\p{L})[^\p{L}\p{N}\s]+(?=\p{L})/gu, '$1');
}

const agora = partesLocais(ctx.agora_iso);
const conteudoNorm = normalizar(ctx.conteudo);
const conteudoGuarda = colapsarLeet(normalizar(juntarLetrasSeparadas(ctx.conteudo)));

// ---------- datas ----------
const DIAS_SEMANA = {
  domingo: 0, segunda: 1, terca: 2, quarta: 3, quinta: 4, sexta: 5, sabado: 6,
};
const MESES = {
  janeiro: 1, fevereiro: 2, marco: 3, abril: 4, maio: 5, junho: 6, julho: 7,
  agosto: 8, setembro: 9, outubro: 10, novembro: 11, dezembro: 12,
};

// 30/02 e "dia 31 de junho" montavam um ISO impossivel e o fluxo morria mais
// adiante sem conseguir dizer ao cliente o que estava errado.
function dataExiste(p) {
  const d = new Date(Date.UTC(p.ano, p.mes - 1, p.dia));
  return d.getUTCDate() === p.dia && d.getUTCMonth() === p.mes - 1;
}

function resolverData(textoData) {
  const t = normalizar(textoData);
  if (!t) return { tipo: null };
  if (/\bhoje\b|\bhj\b|\bagora\b/.test(t)) return { tipo: 'dia', p: agora, ambiguo: false };
  if (/depois de amanha/.test(t)) return { tipo: 'dia', p: somarDias(agora, 2), ambiguo: false };
  if (/\bamanha\b/.test(t)) return { tipo: 'dia', p: somarDias(agora, 1), ambiguo: false };

  const dm = t.match(/\b(\d{1,2})[/-](\d{1,2})(?:[/-](\d{2,4}))?\b/);
  if (dm) {
    const dia = Number(dm[1]); const mes = Number(dm[2]);
    let ano = dm[3] ? Number(dm[3]) : agora.ano;
    if (ano < 100) ano += 2000;
    if (dia >= 1 && dia <= 31 && mes >= 1 && mes <= 12) {
      let p = { ano, mes, dia };
      // Data recente no passado continua no passado: quem falou "19/08" ontem
      // precisa ouvir que ja passou, e nao ser jogado para o ano que vem.
      if (!dm[3]) {
        const candidato = Date.UTC(ano, mes - 1, dia);
        const hoje = Date.UTC(agora.ano, agora.mes - 1, agora.dia);
        if (candidato < hoje - 60 * 86400000) p = { ano: ano + 1, mes, dia };
      }
      if (!dataExiste(p)) return { tipo: 'dia', invalida: true };
      return { tipo: 'dia', p, ambiguo: false };
    }
  }

  const dmExtenso = t.match(/\bdia (\d{1,2})(?: de ([a-z]+))?/);
  if (dmExtenso) {
    const dia = Number(dmExtenso[1]);
    const mesDito = dmExtenso[2] && MESES[dmExtenso[2]] ? MESES[dmExtenso[2]] : null;
    let p = { ano: agora.ano, mes: mesDito || agora.mes, dia };
    // Sem mes dito, "dia 15" no dia 20 e o mes que vem, nao uma data vencida.
    if (!mesDito && Date.UTC(p.ano, p.mes - 1, p.dia) < Date.UTC(agora.ano, agora.mes - 1, agora.dia)) {
      p = p.mes === 12 ? { ano: p.ano + 1, mes: 1, dia } : { ano: p.ano, mes: p.mes + 1, dia };
    }
    if (!dataExiste(p)) return { tipo: 'dia', invalida: true };
    return { tipo: 'dia', p, ambiguo: false };
  }

  // "Semana que vem" numa quinta cobria quinta a quarta e perdia o inicio da
  // semana seguinte. A referencia e a proxima segunda.
  const proxSeg = somarDias(agora, ((8 - agora.dow) % 7) || 7);
  if (/semana que vem|proxima semana/.test(t)) {
    return { tipo: 'janela', p: proxSeg, dias: 6, ambiguo: false };
  }

  for (const nome of Object.keys(DIAS_SEMANA)) {
    if (new RegExp(`\\b${nome}`).test(t)) {
      const alvo = DIAS_SEMANA[nome];
      const proxima = /que vem|proxim/.test(t);
      const base = proxima ? proxSeg : agora;
      const delta = (alvo - base.dow + 7) % 7;
      const ambiguo = !proxima && delta === 0 && !/\bhoje\b/.test(t);
      return { tipo: 'dia', p: somarDias(base, delta), ambiguo, nome_dia: nome };
    }
  }
  return { tipo: null };
}

function semDatas(t) {
  // Remove datas antes de procurar hora: "14/03" nao pode virar 14h.
  return t.replace(/\b\d{1,2}[/-]\d{1,2}(?:[/-]\d{2,4})?\b/g, ' ');
}

function ajustarTurno(t, hora) {
  if (hora <= 11 && /da tarde|a tarde/.test(t)) return hora + 12;
  if (hora <= 11 && /da noite|a noite/.test(t)) return hora + 12;
  return hora;
}

function horaValida(h) { return Number.isFinite(h) && h >= 0 && h <= 23; }

// "depois das 18h", "entre 14 e 16h" e "antes das 11" nao sao horario exato:
// sao a janela em que o cliente aceita ser atendido.
// Numero por extenso vira algarismo antes das tres formas de janela: "so posso
// ate as dez" tem de valer o mesmo que "ate as 10h". Feito aqui, e nao dentro de
// cada expressao, porque as tres ja estao afinadas e mexer nelas custaria mais.
function comAlgarismos(t) {
  let saida = t;
  for (const palavra of Object.keys(HORA_ESCRITA)) {
    saida = saida.replace(new RegExp(`\\b${palavra}\\b`, 'g'), String(HORA_ESCRITA[palavra]));
  }
  return saida;
}

function janelaDeBusca(bruto) {
  // Só troca quando o texto traz uma das ancoras de janela: fora delas, "uma" e
  // "duas" sao contagem ("vou levar uma hora", "para duas pessoas") e virariam
  // numero solto no meio da frase.
  const t = /\b(?:entre|depois|a partir|apos|antes|ate)\b/.test(bruto)
    ? comAlgarismos(bruto) : bruto;
  const entre = t.match(/\bentre (?:as )?(\d{1,2})(?:[:h]\d{2})?\s*(?:h|hs|horas)?\s*e\s*(?:as )?(\d{1,2})/);
  if (entre) {
    const hIni = ajustarTurno(t, Number(entre[1])); const hFim = ajustarTurno(t, Number(entre[2]));
    if (horaValida(hIni) && horaValida(hFim) && hIni < hFim) return { hIni, hFim };
    return null;
  }
  const depois = t.match(/\b(?:depois d[ae]s?|a partir d[ae]s?|apos (?:as )?)\s*(\d{1,2})/);
  if (depois) {
    const hIni = ajustarTurno(t, Number(depois[1]));
    if (horaValida(hIni) && hIni < DIA_FIM) return { hIni, hFim: DIA_FIM };
    return null;
  }
  const antes = t.match(/\b(?:antes d[ae]s?|ate (?:as )?)\s*(\d{1,2})/);
  if (antes) {
    const hFim = ajustarTurno(t, Number(antes[1]));
    if (horaValida(hFim) && hFim > DIA_INICIO) return { hIni: DIA_INICIO, hFim };
    return null;
  }
  return null;
}

function horaExata(t, exigeMarcador) {
  if (/meio[ -]?dia/.test(t)) return { hora: 12, min: 0 };
  // "15 pras 3" e 2h45, nao 15h.
  const pras = t.match(/\b(\d{1,2})\s*(?:pras|pra as|para as)\s*(\d{1,2})\b/);
  if (pras) {
    const alvo = ajustarTurno(t, Number(pras[2]));
    const falta = Number(pras[1]);
    if (horaValida(alvo) && falta > 0 && falta < 60) {
      return { hora: (alvo + 23) % 24, min: 60 - falta };
    }
  }
  const re = /(\bas|\bpras|\bpelas)?\s*\b(\d{1,2})(?:\s*[:h]\s*(\d{2}))?\s*(h|hs|horas)?\b/g;
  let m = re.exec(t);
  while (m !== null) {
    const min0 = m[3] === undefined ? 0 : Number(m[3]);
    let hora = Number(m[2]);
    const resto = t.slice(m.index + m[0].length);
    let min = min0;
    let composto = true;
    if (/^\s*e\s*meia\b/.test(resto)) min = 30;
    else if (/^\s*e\s*quinze\b/.test(resto)) min = 15;
    else if (/^\s*e\s*quarenta e cinco\b/.test(resto)) min = 45;
    else if (/^\s*e\s*trinta\b/.test(resto)) min = 30;
    else composto = false;
    const daManha = /^\s*d[ae]\s*manha\b/.test(resto);
    const turno = /^\s*d[ae]\s*(?:manha|tarde|noite)\b/.test(resto);
    const marcado = !!m[1] || !!m[4] || m[3] !== undefined || composto || turno;
    hora = ajustarTurno(t, hora);
    const aceita = horaValida(hora) && min <= 59
      // Numero nu no texto bruto vira hora so com marcador: sem isso "dia 15"
      // virava 15h e "10 sessoes" virava 10h.
      && !(exigeMarcador && !marcado)
      // Numero baixo tambem precisa de marca: "as 7" e "7 da manha" valem.
      && !(hora <= 7 && !m[1] && !m[4] && m[3] === undefined && !composto && !daManha);
    if (aceita) return { hora, min };
    m = re.exec(t);
  }
  return null;
}

// Hora por extenso e a forma dominante em transcricao de audio, e era descartada
// em silencio: quem pedia "as dez" ouvia "9h ou 12h" e concluia que nao havia
// vaga as dez. Mapa proprio e curto - uma a doze cobre o relogio falado.
const HORA_ESCRITA = {
  uma: 1, um: 1, duas: 2, dois: 2, tres: 3, quatro: 4, cinco: 5, seis: 6,
  sete: 7, oito: 8, nove: 9, dez: 10, onze: 11, doze: 12,
};
// So vale com marca explicita: preposicao antes ("as duas"), "e meia" depois ou
// turno do dia ("duas da tarde"). Sem a marca, "vou levar uma hora", "duas
// pessoas" e "tres sessoes" virariam horario.
const RE_HORA_ESCRITA = new RegExp(
  '(?:\\b(as|pras|pelas)\\s+)?\\b(' + Object.keys(HORA_ESCRITA).join('|') + ')\\b'
  + '(\\s+e\\s+meia\\b)?(\\s+d[ae]\\s+(?:manha|tarde|noite)\\b)?', 'g',
);
function horaPorExtenso(t) {
  const re = new RegExp(RE_HORA_ESCRITA.source, 'g');
  let m = re.exec(t);
  while (m !== null) {
    // O primeiro numero escrito da frase pode ser contagem ("tres sessoes as
    // dez"): a varredura continua ate achar um que esteja marcado.
    // Numero baixo por extenso exige o turno do dia: falado, "as duas" quase
    // sempre e 14h, mas ler 2h transformava uma oferta generica em "ninguem
    // atende nesse horario" - errado e pior do que nao entender. Com "da tarde"
    // a leitura e certa. "as dez" nao tem esse problema.
    // ponytail: o mesmo empate existe no caminho dos digitos ("as 2"); resolver
    // os dois de uma vez pede evidencia de conversa real, nao um palpite aqui.
    if ((m[1] || m[3] || m[4]) && (HORA_ESCRITA[m[2]] > 7 || m[4])) {
      const hora = ajustarTurno(t, HORA_ESCRITA[m[2]]);
      if (horaValida(hora)) return { hora, min: m[3] ? 30 : 0 };
    }
    m = re.exec(t);
  }
  return null;
}

// Devolve { hora, min } ou { periodo_custom: { hIni, hFim } }.
// periodo_custom e janela de busca, nao horario exato: consumido por montarBusca.
function resolverHora(textos) {
  const lista = Array.isArray(textos) ? textos : [textos];
  for (let i = 0; i < lista.length; i += 1) {
    const t = semDatas(normalizar(lista[i]));
    if (!t) continue;
    const janela = janelaDeBusca(t);
    if (janela) return { periodo_custom: janela };
    // A entidade extraida pela IA (indice 0) pode trazer numero nu; o texto
    // bruto que vem depois dela precisa de marcador.
    const h = horaExata(t, i > 0);
    if (h) return h;
    // Digito primeiro: em "as 10h (as dez)" os dois dizem a mesma coisa e o
    // digito e o mais preciso.
    const he = horaPorExtenso(t);
    if (he) return he;
  }
  return null;
}

// ---------- catalogo ----------
// Servico com agendavel: false nunca teria horario livre. Ele continua no
// catalogo para responder duvida de preco, mas sai das listas de oferta.
const AGENDAVEIS = ctx.servicos.filter((s) => s.agendavel !== false);
function nomesAgendaveis() { return AGENDAVEIS.map((s) => s.nome); }

// Substring sem fronteira casava "Barba" dentro de "Barbara".
function contemFrase(texto, frase) {
  if (!frase) return false;
  const escapada = frase.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  return new RegExp(`(^|[^a-z0-9])${escapada}([^a-z0-9]|$)`).test(texto);
}

// "Corte" e "Corte e barba" casavam juntos e viravam ambiguidade: fica so a
// mencao mais especifica.
function maisEspecificos(itens) {
  return itens.filter((a) => !itens.some((b) => {
    const na = normalizar(a.nome); const nb = normalizar(b.nome);
    return nb.length > na.length && contemFrase(nb, na);
  }));
}

// A parte negada nao filtra: "nao com o Rafael" nao pode virar ambiguidade.
function semNegacao(consulta) {
  return normalizar(consulta).split(/\b(?:nao|sem|menos|exceto)\b/)[0].trim();
}

function tokensNome(s) {
  return normalizar(s).split(' ').filter((t) => t.length >= 3 && TITULOS.indexOf(t) === -1);
}

// Prefixo minimo para casar nome de servico com o que o cliente escreveu. Quatro
// letras cobrem conjugacao ("cortar" -> "Corte") e erro de digitacao ("cortr")
// sem transformar qualquer palavra em servico.
const PREFIXO_SERVICO = 4;
function citadoNaMensagem(nome, texto) {
  const alvo = normalizar(nome);
  if (contemFrase(texto, alvo)) return true;
  // O tamanho entra junto do prefixo: conjugacao e erro de digitacao mudam o
  // fim da palavra ("cortar", "cortr", "corti" por "corte"), mas nome proprio
  // que comeca igual e mais longo - sem esta regra "Barbara" virava "Barba".
  const raizes = tokensNome(alvo).filter((t) => t.length >= PREFIXO_SERVICO);
  if (!raizes.length) return false;
  return tokensNome(texto).some((t) => t.length >= PREFIXO_SERVICO
    && raizes.some((raiz) => Math.abs(t.length - raiz.length) <= 1
      && t.slice(0, PREFIXO_SERVICO) === raiz.slice(0, PREFIXO_SERVICO)));
}

// A negacao posposta ("barba nao") e tao comum quanto a preposta ("sem barba"),
// e `semNegacao` so cortava a segunda. Oracao com marca de negacao sai inteira.
function semOracaoNegada(texto) {
  // A quebra e feita no texto CRU: `normalizar` troca pontuacao por espaco, e
  // depois dela nao existe mais virgula para partir - a funcao inteira era
  // codigo morto e "quero o corte, barba nao" seguia ambiguo.
  const partes = String(texto === null || texto === undefined ? '' : texto)
    .split(/[,;]|\se\s/)
    .map((parte) => normalizar(parte))
    .filter((parte) => parte && !/\b(?:nao|sem|menos|exceto|nem)\b/.test(parte));
  return partes.join(' ').trim();
}

// Servico que a mensagem deste turno aponta, inclusive por raiz. Vale para o
// texto que sai agora - o guard de preco precisa saber com qual servico comparar
// quando o cliente diz "quanto custa a drenagem?" e o modelo responde so "fica
// R$ X" sem repetir o nome.
function servicoDoTurno() {
  const achado = acharServico(null);
  if (achado.status !== 'ok') return null;
  return {
    id: achado.servico.id,
    nome: achado.servico.nome,
    duracao_minutos: achado.servico.duracao_minutos,
    valor: achado.servico.valor,
  };
}

// A memoria dura 6 h e agenda sem perguntar: para ela, so vale nome dito por
// inteiro. A raiz ("indicaram" ~ "individual", "avaliando" ~ "Avaliacao") serve
// no turno em que o cliente pede horario, onde o texto de confirmacao nomeia o
// servico e ele pode corrigir - nao para lembrar horas depois.
function servicoCitado() {
  const achado = servicoDoTurno();
  if (!achado) return null;
  if (!contemFrase(conteudoNorm, normalizar(achado.nome))) return null;
  return achado;
}

// Entre candidatos, fica quem a mensagem explicou melhor. Sem isto, o nome mais
// longo vencia sempre: "quero um corte" agendava "Corte e barba" - 30 min a mais
// de agenda e R$ 30 a mais na conta, calados, no caminho feliz.
function melhorCobertura(itens, texto) {
  if (itens.length < 2 || !texto) return itens;
  const nota = (s) => {
    const raizes = tokensNome(normalizar(s.nome));
    if (!raizes.length) return 0;
    return raizes.filter((r) => citadoNaMensagem(r, texto)).length / raizes.length;
  };
  const notas = itens.map(nota);
  const teto = Math.max.apply(null, notas);
  return itens.filter((item, i) => notas[i] === teto);
}

function acharServico(consulta) {
  const q = semNegacao(consulta);
  const lista = ctx.servicos;
  if (!lista.length) return { status: 'catalogo_vazio' };
  // A negacao sai antes da varredura: "quero so o corte, barba nao" ja disse
  // qual e, e reperguntar e ignorar a resposta que o cliente deu.
  const dito = semOracaoNegada(ctx.conteudo) || conteudoNorm;
  // Cobertura antes de especificidade: primeiro quem a mensagem explicou melhor,
  // e so entre esses o nome mais completo vence ("corte e barba" continua sendo
  // o combo, "corte" sozinho volta a ser o corte).
  const mencionados = maisEspecificos(
    melhorCobertura(lista.filter((s) => citadoNaMensagem(s.nome, dito)), dito),
  );
  if (mencionados.length > 1) {
    // "me machuquei na barba, quero so o corte": os dois nomes aparecem, mas um
    // deles vem depois de "so". O cliente ja escolheu.
    const soEste = mencionados.filter((s) => new RegExp(
      `\\b(?:so|apenas|somente)\\s+(?:os?|as?)?\\s*${normalizar(s.nome).slice(0, PREFIXO_SERVICO)}`,
    ).test(dito));
    if (soEste.length === 1) return { status: 'ok', servico: soEste[0] };
    return { status: 'ambiguo', opcoes: mencionados };
  }
  if (!q) {
    if (mencionados.length === 1) return { status: 'ok', servico: mencionados[0] };
    // Catalogo de um servico so: perguntar "qual desses?" com uma opcao e ruido.
    if (lista.length === 1 && AGENDAVEIS.length === 1) return { status: 'ok', servico: AGENDAVEIS[0] };
    return { status: 'ausente' };
  }
  const exato = lista.filter((s) => normalizar(s.nome) === q);
  if (exato.length === 1) return { status: 'ok', servico: exato[0] };
  const contem = maisEspecificos(lista.filter((s) => contemFrase(normalizar(s.nome), q) || contemFrase(q, normalizar(s.nome))));
  if (contem.length === 1) return { status: 'ok', servico: contem[0] };
  if (contem.length > 1) return { status: 'ambiguo', opcoes: contem };
  const porToken = maisEspecificos(
    melhorCobertura(lista.filter((s) => citadoNaMensagem(s.nome, q)), q),
  );
  if (porToken.length === 1) return { status: 'ok', servico: porToken[0] };
  if (porToken.length > 1) return { status: 'ambiguo', opcoes: porToken };
  return { status: 'nao_encontrado' };
}

function acharProfissional(consulta) {
  const q = semNegacao(consulta);
  if (!q) return { status: 'ausente' };
  const qt = tokensNome(q);
  if (!qt.length) return { status: 'ausente' };
  // Token inteiro, sem titulo: "Mariana" nao e a "Ana" e "dra Paula" nao e o
  // "Dr. Joao" so porque os dois tem "dr".
  const achados = ctx.profissionais.filter((p) => {
    const n = normalizar(p.nome);
    return n === q || tokensNome(n).some((t) => qt.indexOf(t) !== -1);
  });
  if (achados.length === 1) return { status: 'ok', profissional: achados[0] };
  if (achados.length > 1) return { status: 'ambiguo', opcoes: achados };
  return { status: 'nao_encontrado' };
}

// A lista sai numerada ("1) ... 2) ..."), entao o numero solto precisa valer.
// O ordinal so conta quando fecha a frase: grudado num substantivo ele e outra
// coisa ("segunda-feira", "primeira vez").
const FECHO_ORDINAL = '(?:\\s+(?:opcao|opcoes|horario|horarios|mesmo|entao|ai|por favor|pfv|pf|obrigad\\w*|valeu|blz|ok|sim))*\\s*$';
const RE_OFERTA_1 = new RegExp(`\\bprimeir[ao]${FECHO_ORDINAL}`);
const RE_OFERTA_2 = new RegExp(`\\bsegund[ao]${FECHO_ORDINAL}`);

// O numero so e escolha quando fecha a mensagem, depois de nada, de um verbo ou
// de uma preposicao: "quero o 1" e "1 por favor" sao escolha; "dia 2" e "2
// pessoas" nao, porque o numero nao fecha a frase. Antes so o numero ancorado
// no inicio valia, e "quero o 1" recebia a mesma lista de volta, sem nem dizer
// que nao entendeu.
const RE_ESCOLHA_NUMERO = new RegExp('(?:^|\\b(?:quero|queria|prefiro|vou querer|pode ser|fica|manda|numero|o|a|e|eh)\\s+(?:o\\s+|a\\s+)?)'
  + '([12])\\b\\s*(?:mesmo|entao|ai|por favor|pfv|pf|obrigad\\w*|valeu|blz|ok)?\\s*$');

// Empate entre "a segunda opcao" e "segunda-feira" numa lista aberta. Fica no
// escopo do modulo porque quem descobre (escolherSlotOferecido) nao e quem
// responde (o ramo de disponibilidade).
let duvidaDiaOuPosicao = false;

function indiceOferta() {
  // "a de segunda" e sempre o dia: em portugues ninguem chama o segundo item de
  // "o de segunda". A preposicao desliga a leitura de posicao antes de tudo.
  if (/\bd[ae]\s+segund/.test(conteudoNorm)) return -1;
  const porOpcao = conteudoNorm.match(/\bopcao\s*([12])\b/);
  if (porOpcao) return Number(porOpcao[1]) - 1;
  const soNumero = conteudoNorm.match(RE_ESCOLHA_NUMERO);
  if (soNumero) return Number(soNumero[1]) - 1;
  if (RE_OFERTA_1.test(conteudoNorm)) return 0;
  if (RE_OFERTA_2.test(conteudoNorm)) return 1;
  // Fora do fecho da mensagem: "a segunda fica melhor pra mim" e "a primeira ja
  // serve" sao escolha do mesmo jeito. "primeira" nao tem leitura de dia; para
  // "segunda", a preposicao desfaz o empate ("a DE segunda" e sempre o dia).
  // "e minha primeira vez ai" nao escolhe opcao nenhuma: o ordinal seguido de
  // "vez" e contagem de visita, nao posicao na lista.
  const ordinalDeVisita = /\b(?:primeir[ao]|segund[ao])\s+(?:vez|vezes)\b/.test(conteudoNorm);
  if (!ordinalDeVisita && /\bprimeir[ao]\b/.test(conteudoNorm)) return 0;
  if (!ordinalDeVisita && /\bsegund[ao]\b/.test(conteudoNorm)
    && !/\bsegunda feira\b/.test(conteudoNorm)) return 1;
  return -1;
}

function mesmoDia(a, b) { return a.ano === b.ano && a.mes === b.mes && a.dia === b.dia; }

function escolherSlotOferecido(entidades) {
  const slots = ctx.estado.slots_oferecidos || [];
  if (!slots.length) return null;
  // "segunda as 14h pode?" nao pode casar as 14h de sexta: o dia citado filtra
  // antes de qualquer casamento por hora.
  const diaDito = resolverData(entidades.date_text);
  const filtraDia = diaDito.tipo === 'dia' && Boolean(diaDito.p) && !diaDito.invalida;
  const candidatos = filtraDia
    ? slots.filter((s) => mesmoDia(partesLocais(s.inicio), diaDito.p))
    : slots;

  // Hora explicita antes do ordinal: "segunda as 14h" cita um dia da semana,
  // nao a segunda opcao.
  const h = resolverHora([entidades.time_text || '', ctx.conteudo]);
  if (h && h.hora !== undefined) {
    const alvo = candidatos.find((s) => {
      const p = partesLocais(s.inicio);
      return p.hora === h.hora && (h.min === 0 || p.min === h.min);
    });
    if (alvo) return alvo;
  }
  // "o das 10": hora nua so vale depois de artigo ou preposicao, e so quando e
  // a hora de um horario ja oferecido. Mesmo criterio do no de consultas.
  const porHoraNua = candidatos.find((s) => new RegExp(`\\b(?:as|das|de|a)\\s+${partesLocais(s.inicio).hora}\\b`).test(conteudoNorm));
  if (porHoraNua) return porHoraNua;
  // Dia citado sem oferta nele: escolher pelo ordinal seria marcar outro dia.
  if (filtraDia && !candidatos.length) return null;

  const indice = indiceOferta();
  if (indice === 1 && /\bsegund[ao]\b/.test(conteudoNorm)
    && slots.some((s) => dowDe(partesLocais(s.inicio)) === 1)) {
    // A lista tem uma oferta de segunda-feira E o cliente disse "segunda": as
    // duas leituras existem e apontam para coisas diferentes. Escolher sozinho
    // marca o dia errado; buscar de novo joga a lista fora sem dizer nada.
    duvidaDiaOuPosicao = true;
    return null;
  }
  if (indice >= 0 && slots[indice]) return slots[indice];
  // Dia da semana citado sem leitura de posicao ("a de segunda", "prefiro na
  // sexta"): se a lista tem exatamente uma oferta nesse dia, ela e a escolha.
  const nomeDia = Object.keys(DIAS_SEMANA).find((nome) => new RegExp(`\\b${nome}`).test(conteudoNorm));
  if (nomeDia) {
    const doDia = candidatos.filter((s) => dowDe(partesLocais(s.inicio)) === DIAS_SEMANA[nomeDia]);
    if (doDia.length === 1) return doDia[0];
  }
  // Contra-pedido depois de uma recusa contem as mesmas palavras do aceite:
  // "pode ser 9h", "quero as 9h" e "9h serve?" casavam este fallback e devolviam
  // o slot unico que o cliente acabou de recusar - o "sim" seguinte gravava
  // justamente o horario recusado. Quem escreve hora ou dia proprios esta
  // pedindo outra coisa; aceitar so vale quando a mensagem nao traz nenhum dos
  // dois. "sim" seco, "ok" e "beleza" nao trazem hora nem dia e continuam
  // fechando a oferta unica, e "pode ser as 16h" com o slot em 16h ja saiu pelo
  // casamento exato la em cima.
  // `candidatos`, nao `slots`: citar o dia ja reduziu a escolha a um, e recusar
  // ali fazia "o de sexta ta otimo" e "hoje mesmo, pode ser" devolverem a mesma
  // pergunta com opcoes que o cliente nunca viu.
  if (!h && candidatos.length === 1 && /\bsim\b|\bpode\b|\bisso\b|\bserve\b|\bquero\b|\bfechado\b|\bbeleza\b|\bok\b|\botim\w*|\bperfeito\b/.test(conteudoNorm)) return candidatos[0];
  return null;
}

// "mais tarde" e "mais cedo" nao dizem hora, mas sao restricao de verdade: sem
// isto a recusa reabria a janela padrao e o bot reoferecia HOJE e um horario 30
// min depois do que o cliente acabou de recusar. Vira `periodo_custom` (piso ou
// teto) no MESMO dia da oferta. So existe com oferta anterior no estado: sem
// referencia nao ha faixa nenhuma a inventar.
function faixaRelativaAOferta() {
  const slots = (ctx.estado.slots_oferecidos || []).filter((s) => s && s.inicio);
  if (!slots.length) return null;
  const maisTarde = /\bmais tarde\b/.test(conteudoNorm);
  const maisCedo = /\bmais cedo\b/.test(conteudoNorm);
  // Nenhum dos dois, ou os dois na mesma frase: nao da para escolher um lado.
  if (maisTarde === maisCedo) return null;
  // A referencia e a oferta do dia em que o cliente esta, nao a ultima da lista:
  // com "quinta 15h" e "sexta 8h" na mesa, "mais tarde" as 14h de quinta quer
  // dizer mais tarde HOJE, e pegar a sexta apagava o dia inteiro.
  const doDia = slots.filter((s) => mesmoDia(partesLocais(s.inicio), agora));
  const lista = doDia.length ? doDia : slots;
  const alvo = partesLocais(maisTarde ? lista[lista.length - 1].inicio : lista[0].inicio);
  // Oferta de um dia que ja acabou nao serve de referencia: afirmar "essa data
  // ja passou" sobre um dia que o cliente nao citou e o mesmo erro que a memoria
  // de data ja evita. Descarta em silencio e o turno segue pela janela padrao.
  if (new Date(isoLocal(alvo, DIA_FIM, 0)).getTime() <= new Date(ctx.agora_iso).getTime()) return null;
  const piso = maisTarde ? alvo.hora + 1 : DIA_INICIO;
  const teto = maisTarde ? DIA_FIM : alvo.hora;
  // Piso acima do fechamento do dia: nao ha "mais tarde" nesse dia. Insistir na
  // faixa vazia devolvia "Nesse horario a gente nao atende" e, como o ramo
  // preserva os slots oferecidos, o turno seguinte repetia a frase byte a byte -
  // parede sem saida. A direcao do pedido continua valendo no proximo dia.
  const exp = expediente(alvo, 0);
  if (maisTarde && piso * 60 >= exp.fim) {
    return { p: somarDias(alvo, 1), periodo_custom: null, proximoDia: true };
  }
  return {
    p: alvo,
    periodo_custom: {
      hIni: Math.max(Math.min(piso, DIA_FIM), DIA_INICIO),
      hFim: Math.max(Math.min(teto, DIA_FIM), DIA_INICIO),
    },
  };
}

function resposta(tipo, dados) {
  return { tipo, dados: dados || {} };
}

// O dia, o periodo e a hora que ESTE turno pediu, para 'montar resposta' gravar
// em estado.data_ultima e o turno seguinte nao comecar do zero: "corte e barba
// amanha as 10h" seguido de "corte" perdia amanha e as 10h e virava busca
// generica de 14 dias. Le interp.entities e nao `ent`, porque as guardas (crise,
// pedido do titular, contraindicacao) chamam saida() antes de `ent` existir.
// null e o sinal de "este turno nao pediu quando nenhum": quem grava mantem o
// que ja estava guardado, e zera quando o assunto fecha.
function pedidoDeData() {
  const e = (interp && interp.entities) || {};
  const d = e.date_text || null;
  const p = e.period || null;
  const h = e.time_text || null;
  return (d || p || h) ? { date_text: d, period: p, time_text: h } : null;
}

function saida(rota, extra) {
  return [{
    json: Object.assign({
      rota,
      contexto: ctx,
      interp: interp,
      // Contrato com 'montar resposta': a mensagem fala de saude, entao o texto
      // livre do modelo nao pode afirmar nada clinico. Fica aqui porque a lista
      // de termos e uma so, e ela mora neste no.
      assunto_clinico: RE_SENSIVEL.test(conteudoGuarda),
      // O TEXTO DO MODELO fala de saude. Junto com `assunto_clinico`, e o que
      // 'montar resposta' usa para nao deixar sair opiniao clinica: uma lista de
      // frases proibidas nunca cobre "pode fazer sim, a massagem ajuda na
      // hernia", e essa e a forma mais natural de errar.
      reply_clinico: RE_SENSIVEL.test(
        colapsarLeet(normalizar(juntarLetrasSeparadas((interp && interp.reply) || '')))
          .replace(RE_PAPELADA, ' '),
      ),
      // Servico citado NESTE turno, so para memoria: nao decide rota nenhuma.
      // Vale em toda saida porque a origem mais comum do esquecimento e a
      // pergunta de preco, que nunca chega a resolver servico para agendar.
      servico_citado: servicoCitado(),
      // Frouxo, so para o texto deste turno (ver `servicoDoTurno`).
      servico_do_turno: servicoDoTurno(),
      // Contrato com 'montar resposta': grava em estado.data_ultima quando nao
      // for null, e zera junto com servico_ultimo no fim do assunto.
      pedido_de_data: pedidoDeData(),
      log: {
        msg_id: ctx.msg_id,
        instance: ctx.instance,
        intent: interp ? interp.intent : null,
        confidence: interp ? interp.confidence : null,
        rota,
      },
    }, extra),
  }];
}

// ---------- pedidos prontos para a API ----------
// Caminho e corpo saem daqui uma unica vez: os nos de escrita e a repeticao
// usam o mesmo objeto, entao repetir nunca muda a chave de idempotencia.
function montarEscrita(p) {
  const base = { instance_name: ctx.instance, telefone: ctx.cliente.telefone };
  if (p.tipo === 'cancelar') {
    return {
      caminho: '/api/ai/agendamentos/cancelar',
      corpo: Object.assign({}, base, { id_consulta: p.consulta_id, motivo: 'cliente_solicitou' }),
    };
  }
  if (p.tipo === 'reagendar') {
    // Reagendar e idempotente por estado: a API recusa chave_idempotencia aqui.
    return {
      caminho: '/api/ai/agendamentos/reagendar',
      corpo: Object.assign({}, base, {
        id_consulta: p.consulta_id,
        novo_inicio: p.inicio,
        id_profissional: p.profissional_id || null,
      }),
    };
  }
  return {
    caminho: '/api/ai/agendamentos',
    corpo: Object.assign({}, base, {
      id_procedimento: p.servico_id,
      id_profissional: p.profissional_id,
      inicio: p.inicio,
      chave_idempotencia: String(p.acao_id || '').slice(0, 120),
    }),
  };
}

function minutosDoRelogio(texto) {
  const m = String(texto === null || texto === undefined ? '' : texto).match(/^(\d{1,2}):(\d{2})/);
  if (!m) return null;
  const h = Number(m[1]); const min = Number(m[2]);
  if (h > 23 || min > 59) return null;
  return h * 60 + min;
}

// Expediente cadastrado manda na janela: com 7h-21h fixos, barbearia que fecha
// as 22h nunca oferecia 21h30 e personal que abre 6h30 nunca oferecia 6h30.
// dia_semana da API e 1=segunda..7=domingo; getUTCDay() e 0=domingo..6=sabado.
// Em janela de varios dias vale o menor inicio e o maior fim do periodo.
function expediente(pDia, dias) {
  const lista = Array.isArray(ctx.horarios) ? ctx.horarios : [];
  let ini = null; let fim = null;
  for (let i = 0; i <= dias; i += 1) {
    const p = i === 0 ? pDia : somarDias(pDia, i);
    const dow = dowDe(p);
    const alvo = dow === 0 ? 7 : dow;
    for (const h of lista) {
      if (Number(h.dia_semana) !== alvo) continue;
      const a = minutosDoRelogio(h.hora_inicio);
      const b = minutosDoRelogio(h.hora_fim);
      if (a === null || b === null || b <= a) continue;
      if (ini === null || a < ini) ini = a;
      if (fim === null || b > fim) fim = b;
    }
  }
  // Quem chama precisa saber a diferenca entre "a empresa fecha aqui" e "nao ha
  // horario cadastrado". Tratar o fallback como fechamento tira 22h de quem nao
  // cadastrou e 6h30 de quem abre cedo; trata-lo como aberto faz o bot dizer
  // "nao achei horario livre" sobre um sabado em que a empresa nem abre.
  if (ini === null || fim === null) {
    return {
      ini: DIA_INICIO * 60,
      fim: DIA_FIM * 60,
      cadastrado: false,
      // Fechado de verdade: a empresa cadastrou expediente, so nao nestes dias.
      fechado: lista.length > 0,
    };
  }
  return { ini, fim, cadastrado: true, fechado: false };
}

// opcoes: { hora: {hora,min}, periodo_custom: {hIni,hFim}, dias }
function montarBusca(pDia, periodo, servicoId, profissionalId, opcoes) {
  const o = opcoes || {};
  const dias = Math.max(0, Math.min(JANELA_MAXIMA_DIAS - 1, Number(o.dias) || 0));
  const exp = expediente(pDia, dias);
  let ini = exp.ini; let fim = exp.fim;
  // "depois das 18h" e "entre 14 e 16h" sao a janela aceita pelo cliente e
  // vencem o periodo nomeado.
  // ponytail: em janela de varios dias isto recorta so as pontas (18h do
  // primeiro dia ate 21h do ultimo), entao "semana que vem depois das 18h"
  // ainda pode trazer slot de manha no meio da semana. O filtro por dia mora
  // no no 'avaliar horarios', que hoje so filtra por `periodo` nomeado.
  // Interseccao, nunca sobrescrita: o periodo recorta o expediente, nao o
  // substitui. Sobrescrevendo, empresa que fecha as 18h e cliente que pede "a
  // noite" geravam busca 18h-21h inteiramente fora do expediente: a API devolvia
  // lista vazia e o cliente ouvia "nao achei horario livre", quando a resposta
  // honesta e que o negocio nao atende a noite. Interseccao vazia cai no ramo
  // fora_do_expediente de irBuscarHorarios, sem chamar a API.
  const faixa = o.periodo_custom
    ? [o.periodo_custom.hIni, o.periodo_custom.hFim]
    : ((periodo && PERIODOS[periodo]) || null);
  if (faixa) {
    // `periodo_custom` e limite que o CLIENTE digitou ("entre 7 e 9", "depois
    // das 7h"): vale sempre, inclusive quando coincide com DIA_INICIO. A isencao
    // abaixo e so para o piso PADRAO dos periodos nomeados.
    // O piso do periodo so vale quando for mais tarde do que a abertura real:
    // DIA_INICIO e a borda de quem nao cadastrou expediente, e aplica-lo a quem
    // abre 6h30 escondia justamente os primeiros horarios do dia - "de manha"
    // passa a significar "da abertura ate o meio-dia".
    if (o.periodo_custom || faixa[0] > DIA_INICIO) ini = Math.max(ini, faixa[0] * 60);
    // DIA_FIM e a borda do dia de quem nao tem expediente cadastrado, nao um
    // fechamento real: recortar por ela repetiria o bug de origem no outro
    // extremo, escondendo o 21h30 de quem fecha as 22h. No comeco do dia o
    // Math.max ja descarta DIA_INICIO sozinho; aqui a simetria e explicita.
    if (faixa[1] < DIA_FIM) fim = Math.min(fim, faixa[1] * 60);
  }
  // Alvo fora do expediente, com a janela ainda util: a API responde sobre a
  // vizinhanca, mas a resposta precisa dizer que naquele horario ninguem atende,
  // em vez de afirmar que o horario esta ocupado.
  let alvoForaDoExpediente = false;
  // Hora pedida recorta a janela em volta dela. `Math.min(ini, alvo)` expandia
  // para fora do expediente: "melhor sabado as 20h" numa empresa que fecha 13h
  // no sabado virava uma busca das 18h as 20h30, inteira depois do fechamento;
  // a API devolvia lista vazia e o cliente ouvia "nao achei horario livre" em
  // vez de saber que ninguem atende aquela hora.
  if (o.hora) {
    const alvo = o.hora.hora * 60 + o.hora.min;
    // Ancorar so vale para hora que o cliente pediu, e so quando existe
    // expediente cadastrado para comparar. Revalidar horario que a propria
    // agenda ofereceu (ignorar_antecedencia) nunca ancora: a API pode ter um
    // encaixe fora da grade e recusar aqui negaria o horario que o fluxo acabou
    // de oferecer. Sem expediente cadastrado tambem nao ancora: 7h-21h e borda
    // de fallback, nao fechamento - trata-la como fechamento some com o 22h de
    // quem nao configurou e com o 6h30 do personal.
    if (o.ignorar_antecedencia) {
      // Revalidar o que a agenda ja ofereceu nao recorta em volta do alvo: se ele
      // ja passou, o recorte levava junto a OUTRA oferta, que continuava de pe -
      // o cliente ouvia "esse horario nao esta livre" e perdia a opcao boa. O dia
      // inteiro, mais o proprio alvo quando ele estiver fora da grade (encaixe).
      ini = Math.min(ini, alvo - PASSO_MINUTOS);
      fim = Math.max(fim, alvo + PASSO_MINUTOS);
    } else {
      const ancorar = exp.cadastrado;
      if (ancorar && (alvo < ini || alvo >= fim)) alvoForaDoExpediente = true;
      const janelaIni = ancorar ? ini : Math.min(ini, alvo - MARGEM_HORA_MIN);
      const janelaFim = ancorar ? fim : Math.max(fim, alvo + MARGEM_HORA_MIN + PASSO_MINUTOS);
      ini = Math.min(Math.max(janelaIni, alvo - MARGEM_HORA_MIN), janelaFim);
      fim = Math.max(Math.min(janelaFim, alvo + MARGEM_HORA_MIN + PASSO_MINUTOS), janelaIni);
    }
  }
  // Vazia aqui significa "o negocio nao atende nessa faixa" - diferente de vazia
  // depois do piso de hoje, que significa "hoje ja nao da tempo". Os dois textos
  // sao diferentes, entao a distincao viaja com o pedido.
  // Dia sem linha de expediente e fechado, nao vazio: perguntar a API e devolver
  // "nao achei horario livre" faz o cliente entender "esta cheio" e insistir.
  const foraDoExpediente = ini >= fim || exp.fechado === true;
  // Comecar no minuto atual fazia o fluxo oferecer um horario para dali a 3
  // minutos, e no "sim" dizer que acabou de ser ocupado.
  const ehHoje = pDia.ano === agora.ano && pDia.mes === agora.mes && pDia.dia === agora.dia;
  // A antecedencia vale para horario novo, nao para revalidar o que o proprio
  // fluxo ofereceu: quem responde 20 minutos depois ouvia "esse horario nao esta
  // livre" sobre o horario que acabou de receber. A flag e explicita porque
  // `horario_desejado` tambem carrega hora digitada pelo cliente, e ai o piso
  // precisa valer.
  if (ehHoje && !o.ignorar_antecedencia) ini = Math.max(ini, agora.hora * 60 + agora.min + ANTECEDENCIA_MIN);
  return {
    instance_name: ctx.instance,
    id_procedimento: servicoId,
    id_profissional: profissionalId || null,
    inicio: isoMin(pDia, ini),
    fim: isoMin(dias ? somarDias(pDia, dias) : pDia, fim),
    passo_minutos: PASSO_MINUTOS,
    limite: LIMITE_SLOTS,
    // Recados internos para irBuscarHorarios, retirados antes de virar corpo da
    // requisicao: a rota recusa campo desconhecido.
    fora_do_expediente: foraDoExpediente,
    // Dia sem expediente cadastrado e caso proprio: "tem horario domingo?" nao
    // pode receber "nesse HORARIO a gente nao atende" - a pergunta era de dia.
    dia_fechado: exp.fechado === true,
    alvo_fora_do_expediente: alvoForaDoExpediente,
  };
}

function horaDoIso(iso) { const p = partesLocais(iso); return { hora: p.hora, min: p.min }; }

// Janela vazia acontece de verdade: "hoje a tarde" perguntado as 20h. A API
// recusaria com ENTRADA_INVALIDA, e isso viraria transferencia por engano.
function irBuscarHorarios(pedido, extra) {
  const busca = Object.assign({}, pedido);
  const foraDoExpediente = busca.fora_do_expediente === true;
  const alvoForaDoExpediente = busca.alvo_fora_do_expediente === true;
  const diaFechado = busca.dia_fechado === true;
  delete busca.fora_do_expediente;
  delete busca.alvo_fora_do_expediente;
  delete busca.dia_fechado;
  // A flag vale por si: em janela de varios dias o `fim` cai no ultimo dia,
  // entao `inicio < fim` sempre e a comparacao de ISO nunca colapsava - "semana
  // que vem as 20h" seguia chamando a API e ignorando o "as 20h" calado.
  if (foraDoExpediente || new Date(busca.inicio).getTime() >= new Date(busca.fim).getTime()) {
    return saida('responder', {
      motivo: 'fora_do_expediente',
      // Nenhuma agenda foi consultada neste caminho. "Nao achei horario livre
      // ate 22/08" afirmava um resultado de busca que nunca aconteceu; quando a
      // faixa esta fora do expediente o honesto e dizer que ninguem atende
      // aquela hora. Janela que so esvaziou pelo piso de hoje continua com o
      // texto de sem_horarios, que ali e verdadeiro.
      resposta: foraDoExpediente
        ? resposta('fora_do_expediente', { servico: extra.servico, dia_fechado: diaFechado })
        : resposta('sem_horarios', { servico: extra.servico, ate: busca.fim }),
      // Este turno nao chega a chamar a agenda, entao nao falou de horario
      // nenhum - muito menos da pendencia anterior. Sem devolver estado aqui,
      // 'montar resposta' repassaria o pendente_falada do turno passado e o
      // "sim" seguinte executaria uma pendencia que o cliente nao ouviu de novo
      // ("melhor sabado as 20h" num sabado que fecha 13h gravava a sexta 16h).
      // As outras tres chaves seguem como estao: pedir uma janela impossivel nao
      // encerra o assunto nem apaga o servico ja escolhido.
      estado_novo: {
        slots_oferecidos: ctx.estado.slots_oferecidos || [],
        consultas_candidatas: ctx.estado.consultas_candidatas || [],
        reagendar_consulta_id: ctx.estado.reagendar_consulta_id || null,
      },
    });
  }
  return saida('disponibilidade', Object.assign({ busca, alvo_fora_do_expediente: alvoForaDoExpediente }, extra));
}

// ---------- decisao ----------
let interp = validacao.interp;

// O webhook nao traz mais base64: a midia e buscada na Evolution por um no
// proprio. Quando essa busca falha o conteudo chega vazio e todo audio virava
// "Nao entendi direito". Dizer que o audio nao foi ouvido e o unico honesto.
const conteudoSemMarcador = String(ctx.conteudo || '').replace(/\[imagem:[^\]]*\]/gi, '').trim();
if (['audio', 'imagem'].includes(ctx.tipo_entrada) && !conteudoSemMarcador) {
  return saida('responder', {
    motivo: 'midia_indisponivel',
    resposta: resposta('audio_nao_ouvido', {}),
  });
}

// Guardas deterministicas: leem so o texto do cliente e nunca a interpretacao,
// entao vem antes do portao da IA. Depois dele, uma queda da OpenAI (timeout,
// 5xx, cota, recusa) respondia "pode mandar de novo" a quem disse que quer
// morrer — sem CVV, sem pausa e sem pessoa avisada. E justamente o conteudo de
// crise que mais faz o provedor falhar, entao o gatilho da falha e o gatilho da
// guarda coincidem. Vale igual para o contexto fora do ar.
const temAutolesao = RE_AUTOLESAO.test(conteudoGuarda)
  && (RE_AUTOLESAO_SINAL_FORTE.test(conteudoGuarda)
    || (RE_AUTOLESAO_SINAL.test(conteudoGuarda) && !RE_CORTE_ESTETICO.test(conteudoGuarda)));
if (RE_CRISE.test(conteudoGuarda) || temAutolesao) {
  return saida('humano', {
    motivo: 'crise',
    handoff_motivo: 'crise',
    resposta: resposta('crise', {}),
  });
}

// Apagar dados ou sair da lista e direito do titular: pessoa decide, nao a IA.
// O texto e o de pedido_do_titular, nao o generico de transferencia: quem pede
// para apagar os dados precisa ouvir que o pedido foi registrado, e nao "isso e
// melhor uma pessoa te responder com calma", que soa como se a IA tivesse
// decidido sozinha. TEXTOS.pedido_do_titular tambem e a unica excecao de
// apresentacao que existia sem nunca disparar.
const pedeOptout = RE_TITULAR_OPTOUT.test(conteudoGuarda) && !RE_OPTOUT_RESTRITO.test(conteudoGuarda);
if (RE_TITULAR_APAGAR.test(conteudoGuarda) || pedeOptout) {
  return saida('humano', {
    motivo: 'pedido_do_titular',
    handoff_motivo: 'pedido_do_titular',
    resposta: resposta('pedido_do_titular', {}),
  });
}

// Contraindicacao nao depende de pergunta nem do modelo. Ela vale em quase
// todo caminho, porque o pior resultado e a IA responder "sem problema nenhum"
// a quem disse que toma anticoagulante. Duas excecoes, e so duas: desmarcar nao
// pode ficar refem da condicao (a gestante precisa conseguir cancelar), e
// confirmar uma acao ja combinada tambem nao. Sem intencao (falha da IA,
// contexto fora do ar) transfere: errar para o lado seguro custa uma conversa,
// nao um procedimento contraindicado.
const intentDoTurno = validacao.valida && interp ? interp.intent : null;
if (RE_CONDICAO.test(conteudoGuarda)
  && !INTENTS_SEM_CONDICAO.includes(intentDoTurno)
  && !RE_CONDICAO_NEGADA.test(conteudoGuarda)
  && !RE_CONDICAO_TERCEIRO.test(conteudoGuarda)) {
  return saida('humano', {
    motivo: 'transferencia',
    handoff_motivo: 'assunto_sensivel',
    resposta: resposta('humano', {}),
  });
}

if (!validacao.valida || !interp) {
  // Timeout, 5xx ou cota da OpenAI e falha nossa e retentavel: transferir e
  // pausar a IA por uma hora por instabilidade de minutos e desproporcional.
  if (validacao.motivo === 'falha_ia') {
    return saida('responder', {
      motivo: 'falha_ia',
      resposta: resposta('esclarecer', { reply: 'Tive uma instabilidade aqui e não consegui ler sua mensagem. Pode mandar de novo, por favor?' }),
    });
  }
  return saida('humano', {
    motivo: validacao.motivo || 'interpretacao_invalida',
    handoff_motivo: 'interpretacao_invalida',
    resposta: resposta('humano', {}),
  });
}

if (!ctx.tem_contexto) {
  return saida('humano', {
    motivo: 'contexto_incompleto',
    handoff_motivo: ctx.erro_contexto || 'contexto_incompleto',
    resposta: resposta('humano', {}),
  });
}

const ent = interp.entities;

// Crise, pedido do titular e contraindicacao ja foram decididos acima, antes do
// portao da IA. RE_CONDICAO saiu daqui pelo mesmo motivo, mas la ela olha a
// intencao: so bloqueia quem esta a caminho de uma oferta de horario.
// A interrogacao sai no normalizar, entao o gatilho "?" precisa do texto bruto.
// Pergunta que fala do corpo do cliente vai para uma pessoa. Tentar reconhecer o
// PEDIDO de orientacao por lista de palavras nunca fechou - "isso e ruim?", "a
// hernia atrapalha o pilates?" e "devo trocar o curativo?" nao tem vocabulario
// em comum. A regra fecha pelo lado seguro e a excecao e o vocabulario do
// proprio negocio, que e enumeravel: servico, agenda, pagamento, documento.
const E_PERGUNTA = new RegExp('\\?|\\bo que\\b|\\bqual\\b|\\bquais\\b|\\bcomo\\b|\\bquando\\b'
  + '|\\bpode\\b|\\bposso\\b|\\bdevo\\b|\\bprecis\\w*|\\bconsigo\\b|\\be normal\\b'
  + '|\\batrapalh\\w*|\\be ruim\\b|\\be sinal\\b|\\bsignifica\\b|\\bserve\\b');
// Assunto que e nosso, nao do corpo do cliente. Cada entrada aqui e uma pergunta
// que a recepcao responde todo dia e que nao pode custar 12 h de silencio.
const ASSUNTO_NOSSO = new RegExp('\\batendem\\b|\\btratam\\b'
  + '|\\b(?:voces|vcs|vc|ai|aqui|voce)\\s+(?:atende\\w*|faz\\w*|trabalh\\w*|trata\\w*|emite\\w*|aceita\\w*)'
  + '|\\btem (?:horario|vaga|agenda)|\\bquanto custa|\\bqual o (?:valor|preco|endereco)'
  + '|\\bpode me (?:atender|encaixar|receber|ver hoje)'
  + '|\\b(?:a|o) \\w+ pode (?:fazer|atender)'
  + '|\\b(?:pode|posso|da pra|consigo|precis\\w*|devo|tenho que) '
  + '(?:marcar|agendar|remarcar|cancelar|encaixar|pagar|levar|trazer|pegar|chegar|estacionar)'
  + '|\\bpagar\\b|\\bcartao\\b|\\bpix\\b|\\bdinheiro\\b|\\bparcel\\w*'
  + '|\\bestacionament\\w*|\\bendereco\\b|\\batestado\\b|\\brecibo\\b|\\bnota fiscal\\b'
  + '|\\bconvenio\\b|\\bplano de saude\\b|\\breceita\\b|\\blaudo\\b|\\breembolso\\b'
  // O vocabulario que o campo "Sobre o negocio" pede ao dono. Sem ele, a
  // pergunta chegava com a queixa junto ("to com dor nas costas, o que levar na
  // primeira sessao?"), a guarda de assunto sensivel via a dor e transferia - com
  // a resposta escrita no cadastro. Colocacao, e nao verbo solto: `\\blevar\\b`
  // faria "isso pode levar a uma lesao?" virar assunto nosso, e essa e
  // justamente a pergunta que tem de ir para uma pessoa.
  + '|\\bo que (?:levar|trazer|levo|trago)\\b|\\bpreciso levar\\b'
  // Colocacao, e nao o verbo solto. `cancelament\\w*` e `remarc\\w*` sozinhos
  // capturavam a frase inteira: "posso desmarcar? minha hernia voltou a doer"
  // deixava de ir para uma pessoa por causa da primeira palavra.
  + '|\\b(?:quero|queria|posso|poderia|preciso|vou|vamos|tenho que|da pra|dava pra'
  + '|gostaria de|como faco para|(?:vou|preciso|tenho|vamos) ter que) '
  + '(?:desmarcar|remarcar|cancelar)\\b'
  + '|\\bcancelamento\\b'
  + '|\\b(?:pode|posso|levar|trazer|leva|com) acompanhante\\b'
  + '|\\b(?:a|em) domicilio\\b');
// O ponto de interrogacao e testado no texto CRU: `normalizar` tira pontuacao, e
// "doi?" perderia justamente a marca de pergunta.
const ehPergunta = /\?/.test(String(ctx.conteudo || '')) || E_PERGUNTA.test(conteudoNorm);
const perguntaSensivel = RE_SENSIVEL.test(conteudoGuarda)
  && ehPergunta
  && !ASSUNTO_NOSSO.test(conteudoNorm)
  && ['faq', 'saudacao', 'fora_do_escopo'].includes(interp.intent);

// A regex de crise e o piso garantido, nao o teto: ela tem falso negativo
// comprovado ("to pensando em fazer uma besteira" nao casa nada). O enum de
// handoff_reason existe justamente para o modelo escalar o que ela perdeu - mas
// enquanto ninguem lia esse campo, escalar nao mudava nada e a pessoa recebia
// "Claro." sem o 188. O modelo so consegue ESCALAR: a guarda deterministica
// roda antes desta linha e ja decidiu sozinha nos casos dela.
if (interp.handoff_reason === 'crise') {
  return saida('humano', {
    motivo: 'crise',
    handoff_motivo: 'crise',
    resposta: resposta('crise', {}),
  });
}

if (interp.requires_human || interp.intent === 'falar_com_humano' || perguntaSensivel) {
  return saida('humano', {
    // Este ramo so tem dois casos, e os dois sao nossos: assunto sensivel ou
    // pedido do cliente. interp.handoff_reason e texto livre do modelo ("cliente
    // pediu atendimento humano"), que nunca batia com 'pedido_do_cliente': o
    // cliente ouvia o generico e a pausa da IA caia de 12h para 1h. O texto do
    // modelo continua disponivel em interp.handoff_reason (ja vai no envelope) e
    // fica fora da chave do Redis e do log, porque pode conter dado pessoal.
    motivo: 'transferencia',
    handoff_motivo: perguntaSensivel ? 'assunto_sensivel' : 'pedido_do_cliente',
    resposta: resposta('humano', {}),
  });
}

const destrutiva = ['preparar_cancelamento', 'preparar_reagendamento', 'confirmar_acao'].includes(interp.intent);
const limiar = destrutiva ? LIMIAR_DESTRUTIVO : LIMIAR_PADRAO;
if (interp.confidence < limiar) {
  return saida('responder', {
    motivo: 'confianca_abaixo_do_limiar',
    resposta: resposta('esclarecer', { reply: interp.reply }),
  });
}

// Confirmacao: so executa a acao pendente guardada pelo sistema.
// Rota do horario que o cliente acabou de escolher na lista oferecida.
function irParaSlotOferecido(alvo, motivo) {
  return irBuscarHorarios(
    montarBusca(partesLocais(alvo.inicio), null, alvo.servico_id, alvo.profissional_id, {
      hora: horaDoIso(alvo.inicio),
      ignorar_antecedencia: true,
    }),
    {
      motivo,
      servico: { id: alvo.servico_id, nome: alvo.servico_nome, duracao_minutos: alvo.duracao_minutos },
      profissional: alvo.profissional_id ? { id: alvo.profissional_id, nome: alvo.profissional_nome } : null,
      horario_desejado: alvo.inicio,
      // Contrato com 'avaliar horarios': o alvo veio de slots_oferecidos, entao
      // o piso de antecedencia nao pode apagar da lista o proprio horario que
      // foi ofertado.
      ignorar_antecedencia: true,
      reagendar_consulta_id: ctx.estado.reagendar_consulta_id,
    },
  );
}

// Escolha desta mensagem que nao e a pendencia guardada: o cliente mudou de
// horario e a pendencia velha nao pode vencer a oferta nova.
// Pista de quando: entidade extraida, hora ou data reconhecida no texto, ou as
// formas vagas que o cliente usa para recusar pedindo ("mais tarde", "outro
// dia"). Vago basta: a busca reabre a janela padrao e reoferece.
function pediuOutroMomento() {
  if (ent.date_text || ent.time_text || ent.period) return true;
  if (resolverHora([ctx.conteudo])) return true;
  const quando = resolverData(ctx.conteudo);
  if (quando && quando.tipo) return true;
  // "nenhum desses serve" nao diz quando, mas pede alternativa do mesmo jeito.
  return /\bmais (?:tarde|cedo)\b|\boutro dia\b|\boutro horario\b|\bde (?:manha|tarde|noite)\b|\bsemana que vem\b|\bproxima semana\b/
    .test(conteudoNorm)
    || /\bnenhum(?:a|s)?\b|\bnao serve\b|\bnao da\b|\bnao posso\b|\bnao consigo\b|\btem outr\w*/
      .test(conteudoNorm);
}

// "hoje ou amanha" e uma janela, nao uma data. `resolverData` pega a primeira e
// ignora o resto: a busca cobria so hoje e o cliente ouvia "nao achei horario"
// com o dia seguinte livre.
function janelaDeAlternativas() {
  const partes = conteudoNorm.split(/\bou\b/).map((t) => t.trim()).filter(Boolean);
  if (partes.length < 2) return null;
  const alvos = [];
  for (const parte of partes) {
    const achado = resolverData(parte);
    if (achado && achado.tipo === 'dia' && !achado.ambiguo) alvos.push(achado.p);
  }
  if (alvos.length < 2) return null;
  const ms = alvos.map((alvo) => new Date(isoLocal(alvo, 12, 0)).getTime());
  const menor = Math.min.apply(null, ms);
  const dias = Math.round((Math.max.apply(null, ms) - menor) / 86400000);
  if (dias < 1 || dias > JANELA_MAXIMA_DIAS - 1) return null;
  return { tipo: 'janela', p: alvos[ms.indexOf(menor)], dias, ambiguo: false };
}

function slotDiferenteDaPendencia(pendente) {
  const alvo = escolherSlotOferecido(ent);
  if (!alvo || !alvo.servico_id) return null;
  if (pendente && pendente.inicio === alvo.inicio) return null;
  return alvo;
}

// descartar_pendente nao conclui o assunto: quem recusa ("nao, tem mais cedo?")
// ou deixa a oferta vencer continua na mesma conversa. Sem devolver o estado
// aqui, o reagendamento em curso virava agendamento novo (duas consultas) e o
// servico ja escolhido sumia, e no vencimento a conversa entrava em laco: o bot
// perguntava "quer que eu procure de novo?" sem ter como honrar o "sim".
function estadoSemPendencia(pendente) {
  return {
    reagendar_consulta_id: (pendente && pendente.tipo === 'reagendar')
      ? pendente.consulta_id
      : (ctx.estado.reagendar_consulta_id || null),
    slots_oferecidos: ctx.estado.slots_oferecidos || [],
    consultas_candidatas: ctx.estado.consultas_candidatas || [],
  };
}

if (interp.next_action === 'confirm_pending') {
  const pendente = ctx.pendente;
  const expirada = Boolean(pendente && pendente.expira_em
    && new Date(pendente.expira_em).getTime() < new Date(ctx.agora_iso).getTime());
  // Toda oferta que nao gera pendencia (dois horarios, horario indisponivel) e
  // todo turno que termina sem oferta nenhuma (sem horarios, fora do expediente,
  // falha da API) deixam a pendencia anterior viva no Redis por ate 10 min. Ai
  // um "sim" marcava o horario que o cliente acabou de recusar - ou, pior, o
  // servico e o horario de um assunto que o turno anterior nem mencionou.
  // O criterio e "o ultimo turno falou dela", nao "a lista de slots contem a
  // pendencia": pela lista, sem_horarios grava [] e a lista vazia era lida como
  // "nao sei" em vez de "nao falei". 'montar resposta' grava em
  // estado.pendente_falada o inicio da pendencia que realmente saiu no texto e
  // 'montar contexto' repassa; so ela pode ser executada por um "sim".
  // A leitura pela lista continua junto, em OU: com a chave ausente do estado
  // (nenhum turno gravou ainda) comparar com undefined invalidaria a pendencia
  // por falta de contrato, e nao por silencio do turno, e nenhum "sim" fecharia
  // horario. Em producao 'montar contexto' sempre emite a chave - ausente no
  // Redis ela sai null, que ja e "nao falei" - e as duas leituras concordam,
  // porque 'montar resposta' grava a marca e a lista de ofertas no mesmo ponto.
  const slotsOferecidos = ctx.estado.slots_oferecidos || [];
  const pendenteFalada = ctx.estado.pendente_falada;
  const pendenteObsoleta = Boolean(pendente && pendente.inicio)
    && ((pendenteFalada !== undefined && pendenteFalada !== pendente.inicio)
      || (slotsOferecidos.length > 0 && !slotsOferecidos.some((s) => s.inicio === pendente.inicio)));
  // Depois de uma segunda oferta, "o das 10" confirmava a pendencia anterior e
  // marcava outro dia. O que o cliente acabou de escolher vem primeiro.
  const trocou = slotDiferenteDaPendencia(pendente);
  if (trocou) return irParaSlotOferecido(trocou, 'selecao_de_horario_oferecido');
  if (expirada) {
    // Rota que apaga a chave: com a pendencia vencida so saindo no TTL, todo
    // "sim" dos 10 minutos seguintes ouvia "esse horario ja expirou".
    return saida('descartar_pendente', {
      motivo: 'pendente_expirada',
      resposta: resposta('pendente_expirada', { tipo: pendente.tipo }),
      estado_novo: estadoSemPendencia(pendente),
    });
  }
  if (pendente && pendente.tipo && !pendenteObsoleta) {
    // A API revalida o horario com a funcao do banco imediatamente antes de
    // gravar, entao o fluxo nao repete a consulta de disponibilidade aqui.
    return saida('executar_pendente', {
      motivo: 'confirmacao_valida',
      pendente,
      escrita: montarEscrita(pendente),
    });
  }
  const alvo = escolherSlotOferecido(ent);
  if (alvo && alvo.servico_id) return irParaSlotOferecido(alvo, 'selecao_de_horario_oferecido');
  // "pode ser 9h" com 15h e 8h na mesa nao e escolha ambigua: e pedido novo, e
  // devolver "e o 1 ou o 2?" ignora o horario que o cliente acabou de dar. Sem
  // hora nem dia na frase, a duvida e real e a pergunta continua valendo.
  if ((ctx.estado.slots_oferecidos || []).length > 1 && !pediuOutroMomento()) {
    return saida('responder', { motivo: 'escolha_ambigua', resposta: resposta('qual_horario', { slots: ctx.estado.slots_oferecidos }) });
  }
  // "a segunda" respondendo a "Qual deles?" chega aqui quando o modelo classifica
  // como confirmar_acao em vez de preparar_cancelamento - um palpite que muda o
  // destino. Negar a pendencia ("nao tenho nada pendente aqui") depois de o
  // proprio bot ter feito a pergunta e o pior desfecho possivel; repetir a lista
  // devolve a escolha ao cliente sem inventar nada e sem campo novo no estado.
  const candidatas = ctx.estado.consultas_candidatas || [];
  if (candidatas.length > 1) {
    return saida('responder', {
      motivo: 'escolha_ambigua_consulta',
      resposta: resposta('escolher_consulta', { consultas: candidatas }),
    });
  }
  // Varios textos do sistema terminam em pergunta de sim/nao ("Quer que eu
  // procure outro?", "Quer que eu chame quem atende?", "Quer que eu liste os
  // seus horarios?"). O "sim" a elas caia aqui e recebia "Nao tenho nada
  // pendente aqui para confirmar. Quer que eu veja horarios?" - outra pergunta
  // de sim/nao, e o "sim" seguinte devolvia a mesma frase, byte a byte, sem
  // saida. Havendo turno anterior na conversa, o "sim" responde alguma coisa:
  // seguir para a busca de horario aproveita o que sobrou no estado (remarcacao
  // em curso, oferta anterior, catalogo de um servico so) e, quando nao sobra
  // nada, termina em "Qual desses voce quer?", pergunta aberta que sai do laco.
  // Nada e gravado por este caminho: ele so consulta horario e volta a oferecer.
  // Sem nenhum turno anterior - "sim" como primeira mensagem da conversa - a
  // negativa e verdadeira e continua sendo a resposta.
  if (!(ctx.estado.historico || []).length) {
    return saida('responder', { motivo: 'sem_pendente', resposta: resposta('sem_pendente', {}) });
  }
}

// "nao, prefiro mais tarde" recusa E pede na mesma frase. Marcado aqui, o turno
// segue para a busca e 'avaliar horarios' tira da lista o que acabou de ser
// recusado - reoferecer o mesmo 9h e a forma mais rapida de perder a conversa.
let recusouOferta = false;
if (interp.next_action === 'discard_pending') {
  // "nao, o das 16" recusa a oferta e escolhe outra na mesma frase. Descartar
  // tudo apagava os slots e o reagendamento em curso, e o cliente ouvia
  // "Ok, deixei como esta" em vez do horario que pediu.
  const alternativo = slotDiferenteDaPendencia(ctx.pendente);
  if (alternativo) return irParaSlotOferecido(alternativo, 'selecao_de_horario_oferecido');
  // Sem pista de quando, encerrar continua sendo a resposta certa: o cliente
  // recusou e nao pediu nada.
  if (!pediuOutroMomento()) {
    return saida('descartar_pendente', {
      motivo: 'cliente_recusou',
      resposta: resposta('pendente_descartada', {}),
      estado_novo: estadoSemPendencia(ctx.pendente),
    });
  }
  // Com pista, o turno vira busca nova (o fluxo segue abaixo).
  recusouOferta = true;
}

if (interp.next_action === 'handoff') {
  return saida('humano', { motivo: 'pedido_do_cliente', handoff_motivo: 'pedido_do_cliente', resposta: resposta('humano', {}) });
}

if (interp.next_action === 'answer') {
  return saida('responder', { motivo: 'resposta_conversacional', resposta: resposta('livre', { reply: interp.reply }) });
}

if (interp.next_action === 'update_customer') {
  const campos = ent.customer_updates || {};
  if (!Object.keys(campos).length) {
    return saida('responder', { motivo: 'cadastro_sem_dado_explicito', resposta: resposta('esclarecer', { reply: interp.reply }) });
  }
  if (campos.email && !/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(campos.email)) delete campos.email;
  if (campos.data_nascimento && !/^\d{4}-\d{2}-\d{2}$/.test(campos.data_nascimento)) {
    const br = String(campos.data_nascimento).match(/^(\d{2})[/-](\d{2})[/-](\d{4})$/);
    if (br) campos.data_nascimento = `${br[3]}-${br[2]}-${br[1]}`;
    else delete campos.data_nascimento;
  }
  if (!Object.keys(campos).length) {
    return saida('responder', { motivo: 'cadastro_invalido', resposta: resposta('esclarecer', { reply: interp.reply }) });
  }
  return saida('atualizar_cadastro', { motivo: 'dados_explicitos', atualizacoes: campos });
}

if (interp.next_action === 'list_appointments') {
  const objetivo = interp.intent === 'preparar_cancelamento' ? 'cancelar'
    : (interp.intent === 'preparar_reagendamento' ? 'reagendar' : 'listar');
  return saida('consultas_do_cliente', { motivo: `consultas_para_${objetivo}`, objetivo });
}

// ---------- disponibilidade ----------
// Depois de uma recusa, o que sobrou no estado e o que o cliente NAO quer: ler
// como escolha devolvia o mesmo horario recusado. O servico da oferta continua
// valendo logo abaixo - o que caiu foi so o horario.
const escolhido = recusouOferta ? null : escolherSlotOferecido(ent);
if (duvidaDiaOuPosicao) {
  return saida('responder', {
    motivo: 'escolha_ambigua',
    resposta: resposta('qual_horario', {
      slots: ctx.estado.slots_oferecidos || [],
      motivo: 'dia_ou_posicao',
    }),
  });
}
// Remarcacao em curso: a consulta escolhida ja trouxe servico e profissional da
// API, entao perguntar "qual servico?" de novo e ruido e trava o fluxo.
const emRemarcacao = ctx.estado.reagendar_consulta_id
  ? (ctx.estado.consultas_candidatas || [])[0] || null
  : null;
// "tem 16h?" ou "tem outras opcoes?" depois de uma oferta chega sem
// service_query: o que ja foi oferecido continua valendo.
const ofertaAnterior = (ctx.estado.slots_oferecidos || [])[0] || null;
// acharServico le a mensagem inteira, entao ele acha o servico escrito pelo
// cliente mesmo quando a IA nao extraiu service_query. Com a oferta anterior na
// frente dele, "na verdade prefiro massagem relaxante na sexta" continuava
// resolvendo para o servico da oferta velha - e agora que o estado sobrevive a
// turnos de conversa solta, essa oferta velha dura bem mais. A oferta so entra
// depois de acharServico nao achar nada. Escolha de slot e remarcacao continuam
// vencendo o texto: ali o cliente apontou um horario ou uma consulta concreta.
const porTexto = acharServico(ent.service_query);
const ofertaVale = !ent.service_query && porTexto.status !== 'ok';
// Servico diferente do que esta sendo remarcado nao e remarcacao. A rota de
// reagendar so troca o horario: mover a consulta antiga para um slot achado
// para OUTRO servico troca o recurso do cliente sem ele ter pedido. Quem nomeia
// outro servico esta comecando um agendamento novo, e a remarcacao sai de cena
// inteira - inclusive o id, senao a pendencia seguinte ainda reagendaria.
const servicoPedido = porTexto.status === 'ok' ? porTexto.servico : null;
// Quem repete a palavra continua remarcando, e o servico da consulta vale:
// "quero remarcar pra sexta, tem massagem relaxante?" e uma remarcacao com uma
// pergunta junto, nao um agendamento novo.
const insisteEmRemarcar = interp.intent === 'preparar_reagendamento'
  || /\b(?:remarc\w*|reagend\w*|adiar)\b|\b(?:mudar|trocar|passar|alterar) (?:o )?(?:horario|dia)\b/
    .test(conteudoGuarda);
// Trocar de servico no meio de uma remarcacao precisa de marca de pedido novo.
// Sem ela, qualquer palavra que resolva para outro servico ("ainda estou
// AVALIANDO o transito" -> Avaliacao fisioterapeutica) matava a remarcacao e
// criava um agendamento novo: o horario antigo ficava e o cliente terminava com
// duas consultas, de servicos diferentes, sem ninguem dizer nada.
const PEDIDO_NOVO = /\b(?:outro|outra|novo|nova|tambem|alem disso|na verdade|em vez|no lugar|mudei de ideia)\b/;
const trocouDeServico = Boolean(emRemarcacao && servicoPedido && !insisteEmRemarcar
  && PEDIDO_NOVO.test(conteudoNorm)
  && emRemarcacao.servico_id && servicoPedido.id !== emRemarcacao.servico_id);
const remarcacaoVale = trocouDeServico ? null : emRemarcacao;
const referencia = escolhido || remarcacaoVale || (ofertaVale ? ofertaAnterior : null);
const servicoDaReferencia = referencia && referencia.servico_id
  ? { id: referencia.servico_id, nome: referencia.servico_nome, duracao_minutos: referencia.duracao_minutos }
  : null;

// Ultimo recurso, depois do texto deste turno e da oferta anterior: o servico
// que o cliente citou num turno passado. Sem ele, qualquer turno sem oferta
// apagava o assunto e o fluxo reperguntava o que ja tinha sido dito.
const servicoLembrado = (ctx.estado.servico_ultimo && ctx.estado.servico_ultimo.id)
  ? ctx.estado.servico_ultimo : null;
const buscaServico = servicoDaReferencia
  ? { status: 'ok', servico: servicoDaReferencia }
  : ((porTexto.status !== 'ok' && servicoLembrado)
    ? { status: 'ok', servico: servicoLembrado } : porTexto);

if (buscaServico.status === 'catalogo_vazio' || !AGENDAVEIS.length) {
  return saida('humano', { motivo: 'catalogo_vazio', handoff_motivo: 'configuracao_incompleta', resposta: resposta('humano', {}) });
}
if (buscaServico.status === 'ambiguo') {
  return saida('responder', { motivo: 'servico_ambiguo', resposta: resposta('qual_servico', { opcoes: buscaServico.opcoes.map((s) => s.nome) }) });
}
if (buscaServico.status === 'nao_encontrado') {
  return saida('responder', { motivo: 'servico_nao_confirmado', resposta: resposta('servico_nao_confirmado', { pedido: ent.service_query, servicos: nomesAgendaveis() }) });
}
if (buscaServico.status === 'ausente') {
  // Nome que nao existe sumia sem uma palavra quando o servico tambem faltava:
  // "queria marcar com a Juliana" respondia so "qual desses voce quer?" e a
  // marcacao seguia com outra pessoa. Corrigir o nome vem antes de perguntar o
  // servico - com o servico junto o fluxo ja avisava, so este ramo e que calava.
  // `ctx.profissionais.length` faz parte da condicao: sem ninguem para listar,
  // o texto vira "Nao consegui confirmar esse nome por aqui." e mais nada -
  // beco sem saida justamente para o autonomo que atende sozinho, que e a
  // persona principal do produto. Ali a pergunta de servico ainda avanca.
  if (ent.professional_query && (ctx.profissionais || []).length
    && acharProfissional(ent.professional_query).status === 'nao_encontrado') {
    return saida('responder', { motivo: 'profissional_nao_confirmado', resposta: resposta('profissional_nao_confirmado', { profissionais: ctx.profissionais.map((p) => p.nome) }) });
  }
  return saida('responder', { motivo: 'servico_ausente', resposta: resposta('qual_servico', { opcoes: nomesAgendaveis() }) });
}

const servico = buscaServico.servico;

if (!servico || !servico.id) {
  return saida('humano', { motivo: 'servico_sem_id', handoff_motivo: 'configuracao_incompleta', resposta: resposta('humano', {}) });
}
// Sem profissional ativo o servico nunca teria vaga: dizer "sem horario" seria
// enganoso, porque nao existe data em que ele apareceria.
if (servico.agendavel === false) {
  // Nao e falha do cliente e nao precisa de pessoa: ele pediu um servico que o
  // proprio catalogo anuncia. Transferir aqui pausava a IA por 12 h e encerrava
  // a conversa de quem so queria marcar outra coisa.
  return saida('responder', {
    motivo: 'servico_sem_agenda',
    resposta: resposta('servico_sem_agenda', {
      servico: servico.nome,
      opcoes: AGENDAVEIS.map((s) => s.nome),
    }),
  });
}

let profissional = null;
if (ent.professional_query) {
  const achado = acharProfissional(ent.professional_query);
  if (achado.status === 'ok') profissional = achado.profissional;
  else if (achado.status === 'ambiguo') {
    return saida('responder', { motivo: 'profissional_ambiguo', resposta: resposta('qual_profissional', { opcoes: achado.opcoes.map((p) => p.nome) }) });
  } else if (achado.status === 'nao_encontrado') {
    return saida('responder', { motivo: 'profissional_nao_confirmado', resposta: resposta('profissional_nao_confirmado', { profissionais: ctx.profissionais.map((p) => p.nome) }) });
  }
}
// Profissional do horario oferecido ou da consulta em remarcacao: pedir de novo
// o nome que a propria API ja devolveu so trava a conversa.
if (!profissional && referencia && referencia.profissional_id) {
  profissional = { id: referencia.profissional_id, nome: referencia.profissional_nome };
}
if (!profissional && ctx.empresa.exige_profissional) {
  return saida('responder', { motivo: 'profissional_obrigatorio', resposta: resposta('qual_profissional', { opcoes: ctx.profissionais.map((p) => p.nome) }) });
}

if (escolhido) {
  return irBuscarHorarios(
    montarBusca(partesLocais(escolhido.inicio), null, servico.id, escolhido.profissional_id, {
      hora: horaDoIso(escolhido.inicio),
      ignorar_antecedencia: true,
    }),
    {
      motivo: 'selecao_de_horario_oferecido',
      servico,
      profissional,
      horario_desejado: escolhido.inicio,
      // Mesmo contrato do irParaSlotOferecido: alvo vindo de slots_oferecidos.
      ignorar_antecedencia: true,
      reagendar_consulta_id: ctx.estado.reagendar_consulta_id,
    },
  );
}

// O dia, o periodo e a hora ditos no turno anterior continuam valendo enquanto o
// cliente nao disser outra coisa. Sem esta memoria, "corte e barba amanha as
// 10h" seguido de "corte" perdia amanha e as 10h e caia na janela generica de 14
// dias: o cliente pedia amanha as 10h e recebia hoje as 15h.
// `pediuOutroMomento()` e o freio, e cobre os dois riscos de uma vez: quem traz
// data, periodo ou hora agora nao pode ser sobreposto pelo que disse antes, e
// quem esta recusando ("mais tarde", "nenhum desses") nao pode receber de volta
// o horario que acabou de recusar.
const dataDoTexto = resolverData(ctx.conteudo);
const quandoLembrado = (!ent.date_text && !ent.period && dataDoTexto.tipo === null
  && !pediuOutroMomento() && ctx.estado.data_ultima) ? ctx.estado.data_ultima : null;

const horaResolvida = resolverHora([ent.time_text || '', ent.date_text || '', ctx.conteudo])
  || (quandoLembrado && quandoLembrado.time_text ? resolverHora([quandoLembrado.time_text]) : null);
// Faixa relativa a oferta ("mais tarde"/"mais cedo") so entra sem hora: "mais
// tarde, umas 16h" e um pedido de 16h, nao uma faixa.
const relativoAOferta = horaResolvida ? null : faixaRelativaAOferta();
// Janela ("depois das 18h") nao e horario exato; segue separada para montarBusca.
const periodoCustom = (horaResolvida && horaResolvida.periodo_custom) ? horaResolvida.periodo_custom
  : (relativoAOferta ? relativoAOferta.periodo_custom : null);
const hora = periodoCustom ? null : horaResolvida;
// Mesma memoria do dia e da hora: "de manha" dito no turno anterior continua
// valendo enquanto o cliente nao pedir outro periodo.
const periodoPedido = ent.period || (quandoLembrado ? quandoLembrado.period : null);

// A entidade extraida pela IA vence a mensagem inteira: com os dois juntos,
// "amanha nao pode, so hoje" resolvia para amanha.
let data = resolverData(ent.date_text);
if (data.tipo === null) data = dataDoTexto;
// "tem 16h?" logo depois de uma oferta: hora sem data usa o dia ja ofertado,
// em vez de abrir a janela padrao de 14 dias.
if (data.tipo === null && !ent.date_text && hora && ofertaAnterior && ofertaAnterior.inicio) {
  // Entre os dias ja oferecidos, o primeiro em que a hora pedida ainda esta no
  // futuro. Fixar no primeiro slot fazia "pode ser 9h" cair em hoje as 9h com a
  // tarde ja em curso, e o cliente ouvia "essa data ja passou" depois de dizer
  // um horario perfeitamente possivel amanha.
  const agoraMs = new Date(ctx.agora_iso).getTime();
  const diasOferecidos = (ctx.estado.slots_oferecidos || [])
    .filter((s) => s && s.inicio).map((s) => partesLocais(s.inicio));
  const util = diasOferecidos.find((p) => new Date(isoLocal(p, hora.hora, hora.min)).getTime() > agoraMs);
  data = { tipo: 'dia', p: util || partesLocais(ofertaAnterior.inicio), ambiguo: false };
}
// A faixa relativa e sempre do dia da oferta recusada: "mais tarde" nunca pode
// virar "amanha de manha", que foi exatamente o que o bot respondia.
if (data.tipo === null && relativoAOferta) {
  data = { tipo: 'dia', p: relativoAOferta.p, ambiguo: false };
}
// Ultimo recurso antes da janela padrao: o dia que o cliente disse num turno
// anterior. Data que nao resolve mais, ficou ambigua ou ja venceu e descartada
// em silencio - responder "essa data ja passou" sobre um dia que o cliente nao
// citou neste turno seria pior do que abrir a janela padrao.
if (data.tipo === null && quandoLembrado && quandoLembrado.date_text) {
  const lembrada = resolverData(quandoLembrado.date_text);
  const inicioLembrado = (lembrada.tipo === 'dia' && lembrada.p && !lembrada.invalida && !lembrada.ambiguo)
    ? isoLocal(lembrada.p, hora ? hora.hora : DIA_FIM, hora ? hora.min : 0)
    : null;
  if (inicioLembrado && new Date(inicioLembrado).getTime() > new Date(ctx.agora_iso).getTime()) {
    data = lembrada;
  }
}

if (data.invalida) {
  return saida('responder', { motivo: 'data_invalida', resposta: resposta('data_invalida', {}) });
}
// Expressao de data nao entendida caia calada na janela de 14 dias. O texto e o
// de data_nao_entendida, nao o reply da IA: so ele diz que o problema foi a data
// e ensina o formato aceito ("dia 12", "sexta de manha"). Sem isso, "pro dia de
// nossa senhora" recebia "Nao entendi direito" e o cliente reescrevia a mesma
// frase.
if (data.tipo === null && ent.date_text) {
  return saida('responder', {
    motivo: 'data_nao_entendida',
    resposta: resposta('data_nao_entendida', {}),
  });
}
// Duas datas ligadas por "ou" viram janela. Com hora exata a leitura seria outra
// ("hoje as 9 ou amanha as 10") e sai fora deste caminho.
if (data.tipo === 'dia' && !data.ambiguo && !hora) {
  const janela = janelaDeAlternativas();
  if (janela) data = janela;
}
if (data.tipo === 'dia' && data.ambiguo) {
  return saida('responder', {
    motivo: 'data_ambigua',
    resposta: resposta('data_ambigua', { nome_dia: data.nome_dia, hoje: isoLocal(agora, 12, 0), proxima: isoLocal(somarDias(agora, 7), 12, 0) }),
  });
}

let horarioDesejado = null;
if (data.tipo === 'dia') {
  const inicioDia = isoLocal(data.p, hora ? hora.hora : DIA_FIM, hora ? hora.min : 0);
  if (new Date(inicioDia).getTime() <= new Date(ctx.agora_iso).getTime()) {
    return saida('responder', {
      motivo: 'data_no_passado',
      resposta: resposta('data_passada', { pedido: ent.date_text || ent.time_text || '', sugestao: isoLocal(somarDias(agora, 1), 9, 0) }),
    });
  }
  if (hora) horarioDesejado = isoLocal(data.p, hora.hora, hora.min);
}

const inicioJanela = data.tipo === 'dia' ? data.p : (data.tipo === 'janela' ? data.p : agora);
const diasJanela = data.tipo === 'dia' ? 0
  : (data.tipo === 'janela' ? (data.dias || 6) : JANELA_PADRAO_DIAS);
const busca = montarBusca(inicioJanela, periodoPedido, servico.id, profissional ? profissional.id : null, {
  hora,
  periodo_custom: periodoCustom,
  dias: diasJanela,
});

return irBuscarHorarios(busca, {
  motivo: 'buscar_horarios',
  servico,
  profissional,
  periodo: periodoPedido,
  periodo_custom: periodoCustom, // consumido por montarBusca
  horario_desejado: horarioDesejado,
  // Ver `trocouDeServico`: nomear outro servico encerra a remarcacao. Sem zerar
  // o id aqui, a pendencia seguinte ainda seria um reagendamento da consulta
  // antiga - com o horario achado para o servico novo.
  // A remarcacao sobrevive a recusa: quem recusou a oferta continua querendo
  // mudar a MESMA consulta, e o id dela pode estar so na pendencia recusada.
  reagendar_consulta_id: trocouDeServico ? null
    : (ctx.estado.reagendar_consulta_id
      || ((recusouOferta && ctx.pendente && ctx.pendente.tipo === 'reagendar')
        ? ctx.pendente.consulta_id : null)),
  recusou_oferta: recusouOferta,
});

// Le o envelope de /api/ai/disponibilidade e decide a resposta. Zero, um ou
// varios horarios sao casos distintos; nenhum horario e inventado nem vem do
// historico. Lista vazia com ok: true e resposta legitima, nao falha.
const MAX_OFERTAS = 2;
// 30 min, nao 10: no WhatsApp o cliente le no onibus e responde depois.
// Alongar nao duplica agendamento - a API revalida na escrita e devolve
// CONFLITO_HORARIO, que vira `horario_ocupado` com reoferta.
const PENDENTE_MINUTOS = 30;
const OFFSET_MIN = -180;
const CHAVE_MAX = 120; // limite de chave_idempotencia aceito pela API
// Ninguem sai de casa em 3 minutos. Oferecer horario colado no agora vira
// "acabou de ser ocupado" no sim seguinte. O no 'resolver e decidir' usa a
// mesma constante com o mesmo valor ao montar a janela de busca.
const ANTECEDENCIA_MIN = 60;

const decisao = $('resolver e decidir').first().json;
const ctx = decisao.contexto;
const envelope = $input.first().json || {};

function numero(v) { const n = Number(v); return Number.isFinite(n) ? n : null; }
function turno(iso) {
  const h = new Date(new Date(iso).getTime() + OFFSET_MIN * 60000).getUTCHours();
  if (h < 12) return 'manha';
  if (h < 18) return 'tarde';
  return 'noite';
}
function dia(iso) { return new Date(new Date(iso).getTime() + OFFSET_MIN * 60000).toISOString().slice(0, 10); }

// Sem envelope (falha de rede, corpo sem `ok`) o resultado e desconhecido, e
// desconhecido nunca vira "nao tem horario".
const temEnvelope = typeof envelope.ok === 'boolean';
const dados = (temEnvelope && envelope.ok === true && envelope.data) ? envelope.data : {};
const falhou = !temEnvelope || envelope.ok !== true;
const codigoErro = temEnvelope && envelope.error ? String(envelope.error.code || '') : 'sem_envelope';

const agoraMs = new Date(ctx.agora_iso).getTime();
const procedimento = dados.procedimento || {};

// Os horarios ja vem no fuso do negocio e todo slot traz id_profissional: a
// API descarta slot sem profissional antes de responder.
// Horarios que o cliente ja viu e recusou no turno anterior. Reoferecer o mesmo
// 9h logo depois de "nenhum desses serve" e a forma mais rapida de perder a
// conversa. A lista some no turno seguinte, junto com o resto do estado.
// Comparacao por instante, nao por texto: a oferta e guardada em UTC e a API
// responde no fuso do negocio - o mesmo horario com duas grafias.
const RECUSADOS = decisao.recusou_oferta === true
  ? (ctx.estado.slots_oferecidos || []).map((s) => new Date(s.inicio).getTime())
    .filter((ms) => !Number.isNaN(ms))
  : [];
const slots = (Array.isArray(dados.slots) ? dados.slots : [])
  .map((s) => ({
    inicio: s.inicio,
    fim: s.fim || null,
    profissional_id: numero(s.id_profissional),
    profissional_nome: String(s.profissional_nome || ''),
    servico_id: numero(procedimento.id) || (decisao.servico ? decisao.servico.id : null),
    servico_nome: String(procedimento.nome || (decisao.servico ? decisao.servico.nome : '')),
    duracao_minutos: numero(procedimento.duracao_minutos) || (decisao.servico ? decisao.servico.duracao_minutos : 60),
  }))
  .filter((s) => s.inicio && s.profissional_id && !Number.isNaN(new Date(s.inicio).getTime()))
  // Horario que veio de slots_oferecidos ou da pendencia esta sendo revalidado,
  // nao oferecido agora: aplicar o piso ali fazia o fluxo apagar da lista o
  // proprio horario que acabou de oferecer e responder "esse horario nao esta
  // livre", que e falso. A flag vem de 'resolver e decidir'; horario que ainda
  // passa continua sendo o que comeca no futuro.
  .filter((s) => new Date(s.inicio).getTime() >= agoraMs + (decisao.ignorar_antecedencia ? 0 : ANTECEDENCIA_MIN * 60000))
  // O periodo pedido vale para a janela inteira, nao so para o primeiro dia:
  // quem pediu "de manha" nao quer as 16h de quinta.
  .filter((s) => !decisao.periodo || turno(s.inicio) === decisao.periodo)
  .filter((s) => RECUSADOS.indexOf(new Date(s.inicio).getTime()) === -1)
  .sort((a, b) => new Date(a.inicio) - new Date(b.inicio));

// Duas ofertas no mesmo dia dao pouca escolha real. Dia diferente vale mais que
// turno diferente; turno so entra quando so existe um dia com vaga.
function escolherDois(lista) {
  if (lista.length <= 1) return lista.slice(0, 1);
  const primeiro = lista[0];
  const outroDia = lista.find((s) => dia(s.inicio) !== dia(primeiro.inicio));
  if (outroDia) return [primeiro, outroDia];
  const outroTurno = lista.find((s) => turno(s.inicio) !== turno(primeiro.inicio));
  if (outroTurno) return [primeiro, outroTurno];
  // Mesmo dia e mesmo turno: o vizinho imediato nao e escolha nenhuma. Quem nao
  // pode as 9h tambem nao pode as 9h30, e a saida dele vira "nao, tem mais
  // tarde?". O mais distante da lista da uma alternativa de verdade.
  return [primeiro, lista[lista.length - 1]];
}

function novaPendencia(slot) {
  const expira = new Date(agoraMs + PENDENTE_MINUTOS * 60000).toISOString();
  const base = {
    // acao_id vira a chave_idempotencia da criacao: repetir a mesma acao
    // devolve o mesmo agendamento em vez de criar um segundo.
    acao_id: `${ctx.msg_id}:${slot.inicio}`.slice(0, CHAVE_MAX),
    inicio: slot.inicio,
    duracao_minutos: slot.duracao_minutos,
    servico_id: slot.servico_id,
    servico_nome: slot.servico_nome,
    profissional_id: slot.profissional_id,
    profissional_nome: slot.profissional_nome,
    criada_em: ctx.agora_iso,
    expira_em: expira,
  };
  if (decisao.reagendar_consulta_id) {
    return Object.assign(base, { tipo: 'reagendar', consulta_id: decisao.reagendar_consulta_id });
  }
  return Object.assign(base, { tipo: 'agendar' });
}

function resultado(tipo, dadosResposta, pendente, oferecidos) {
  return [{
    json: {
      tipo_resposta: tipo,
      dados: dadosResposta || {},
      pendente_novo: pendente || null,
      estado_novo: {
        slots_oferecidos: oferecidos || [],
        consultas_candidatas: [],
        reagendar_consulta_id: pendente ? null : (decisao.reagendar_consulta_id || null),
        // Contrato com 'resolver e decidir': so a pendencia criada agora foi
        // anunciada neste turno. Os tipos que nao criam pendencia (dois
        // horarios, horario indisponivel, sem horarios, falha temporaria) zeram
        // o campo, e ai o "sim" do proximo turno nao executa a pendencia velha
        // que ninguem mencionou - antes disso, um turno terminado sem oferta
        // gravava servico e horario de um assunto ja abandonado.
        pendente_falada: pendente ? pendente.inicio : null,
      },
      log: Object.assign({}, decisao.log, {
        tipo_resposta: tipo,
        slots_encontrados: slots.length,
        total: numero(dados.total),
        truncado: dados.truncado === true,
        erro_ferramenta: falhou ? codigoErro : null,
      }),
    },
  }];
}

if (falhou) {
  return resultado('falha_temporaria', { operacao: 'consulta_de_horarios' }, null, ctx.estado.slots_oferecidos);
}

// truncado: a API cortou a lista no limite pedido, entao existem mais opcoes
// alem das duas ofertadas.
const maisOpcoes = dados.truncado === true;

if (decisao.horario_desejado) {
  const alvoMs = new Date(decisao.horario_desejado).getTime();
  const exato = slots.find((s) => new Date(s.inicio).getTime() === alvoMs);
  if (exato) {
    return resultado('pedir_confirmacao', { slot: exato, reagendamento: Boolean(decisao.reagendar_consulta_id) }, novaPendencia(exato), [exato]);
  }
  const alternativas = escolherDois(slots);
  if (!alternativas.length) {
    return resultado('sem_horarios', { servico: decisao.servico, ate: decisao.busca.fim }, null, []);
  }
  // O alvo abaixo do piso de antecedencia nunca chegou a ser pedido a API: a
  // janela de busca comeca depois dele. Dizer "esse horario nao esta livre"
  // seria afirmar sobre um horario que pode estar perfeitamente livre - so esta
  // perto demais para quem ainda precisa sair de casa.
  const emCimaDaHora = !decisao.ignorar_antecedencia
    && alvoMs >= agoraMs
    && alvoMs < agoraMs + ANTECEDENCIA_MIN * 60000;
  // Horario que ja passou nao esta ocupado: dizer "nao esta livre" e falso, e o
  // cliente que demorou a responder merece saber que o relogio e que andou.
  const jaPassou = alvoMs < agoraMs;
  return resultado('horario_indisponivel', {
    pedido: decisao.horario_desejado,
    slots: alternativas,
    em_cima_da_hora: emCimaDaHora,
    ja_passou: jaPassou,
    // Vem de 'resolver e decidir': a hora pedida esta fora do expediente
    // cadastrado. A busca ainda encostou na janela e trouxe vizinhos, mas dizer
    // "nao esta livre" sobre uma hora em que a empresa nem abre e falso.
    fora_do_expediente: decisao.alvo_fora_do_expediente === true,
  }, null, alternativas);
}

if (!slots.length) {
  return resultado('sem_horarios', { servico: decisao.servico, ate: decisao.busca.fim }, null, []);
}

const ofertas = escolherDois(slots);
if (ofertas.length === 1) {
  return resultado('pedir_confirmacao', { slot: ofertas[0], unico: true, reagendamento: Boolean(decisao.reagendar_consulta_id) }, novaPendencia(ofertas[0]), ofertas);
}
return resultado(
  'dois_horarios',
  { slots: ofertas, servico: decisao.servico, mais_opcoes: maisOpcoes || slots.length > ofertas.length },
  null,
  ofertas,
);

// Le o envelope da API depois da escrita. So existe sucesso com ok: true E
// data.agendamento.id; qualquer outra coisa tem rota fixa e nenhuma delas
// anuncia sucesso ao cliente. `repetida: true` tambem e sucesso: a API
// devolveu o mesmo agendamento em vez de criar um segundo.
const OFFSET_MIN = -180;
const DIAS = ['domingo', 'segunda-feira', 'terça-feira', 'quarta-feira', 'quinta-feira', 'sexta-feira', 'sábado'];

// O horario saiu da agenda entre a oferta e o "sim": reoferta, sem pessoa.
const REOFERTAR_HORARIO = ['HORARIO_INDISPONIVEL', 'CONFLITO_HORARIO'];
// O catalogo mudou: reoferta o que existe hoje, sem pessoa.
const REOFERTAR_CATALOGO = ['PROCEDIMENTO_INVALIDO', 'PROFISSIONAL_INVALIDO'];
// A consulta nao e mais reagendavel, ja foi concluida ou nao e deste cliente:
// lista de novo. Nada disso e defeito de sistema, entao a IA continua.
const LISTAR_DE_NOVO = ['CONSULTA_NAO_ENCONTRADA', 'CONSULTA_NAO_REAGENDAVEL', 'CONSULTA_NAO_CANCELAVEL'];

const decisao = $('resolver e decidir').first().json;
const ctx = decisao.contexto;
const pendente = decisao.pendente || {};
const envelope = $input.first().json || {};

function pad(n) { return String(n).padStart(2, '0'); }
function quando(iso) {
  const d = new Date(new Date(iso).getTime() + OFFSET_MIN * 60000);
  const m = d.getUTCMinutes();
  const hora = m ? `${d.getUTCHours()}h${pad(m)}` : `${d.getUTCHours()}h`;
  return `${DIAS[d.getUTCDay()]} (${pad(d.getUTCDate())}/${pad(d.getUTCMonth() + 1)}) às ${hora}`;
}

const temEnvelope = typeof envelope.ok === 'boolean';
const dados = envelope.data || {};
const agendamento = dados.agendamento || null;
const id = agendamento && Number.isFinite(Number(agendamento.id)) ? Number(agendamento.id) : null;
const codigo = temEnvelope && envelope.error ? String(envelope.error.code || '') : '';

// O horario anunciado e o que a API confirmou ter gravado, nao o que pedimos.
const inicioConfirmado = (agendamento && agendamento.inicio) || pendente.inicio || null;
const nomeServico = (agendamento && agendamento.procedimento && agendamento.procedimento.nome)
  || pendente.servico_nome || 'seu atendimento';
const nomeProfissional = (agendamento && agendamento.profissional && agendamento.profissional.nome)
  || pendente.profissional_nome || '';
const prof = nomeProfissional ? ` com ${nomeProfissional}` : '';
const resumo = inicioConfirmado ? `${nomeServico}, ${quando(inicioConfirmado)}${prof}` : 'seu atendimento';

const nomesAgendaveis = (ctx.servicos || []).filter((s) => s.agendavel !== false).map((s) => s.nome);
const nomesProfissionais = (ctx.profissionais || []).map((p) => p.nome);

let tipo;
let sucesso = false;
let precisaHumano = true;
let dadosResposta = {};

if (!temEnvelope) {
  // Sem envelope o resultado e desconhecido: nada pode ser afirmado.
  tipo = 'falha_ferramenta';
  dadosResposta = { operacao: pendente.tipo || null };
} else if (envelope.ok === true && id) {
  sucesso = true;
  precisaHumano = false;
  tipo = pendente.tipo === 'cancelar' ? 'cancelado' : (pendente.tipo === 'reagendar' ? 'reagendado' : 'agendado');
  dadosResposta = { resumo, consulta_id: id };
} else if (envelope.ok === true) {
  tipo = 'resultado_sem_id';
} else if (REOFERTAR_HORARIO.includes(codigo)) {
  precisaHumano = false;
  tipo = 'horario_ocupado';
} else if (codigo === 'PROFISSIONAL_INVALIDO') {
  precisaHumano = false;
  tipo = 'profissional_nao_confirmado';
  dadosResposta = { profissionais: nomesProfissionais };
} else if (REOFERTAR_CATALOGO.includes(codigo)) {
  precisaHumano = false;
  tipo = 'servico_nao_confirmado';
  dadosResposta = { servicos: nomesAgendaveis };
} else if (LISTAR_DE_NOVO.includes(codigo)) {
  precisaHumano = false;
  tipo = 'consulta_nao_encontrada';
} else {
  // Fecha por padrao: autenticacao, instancia, empresa, entrada invalida,
  // chave conflitante, agendamento inativo, falha temporaria persistente e
  // qualquer codigo novo param aqui e chamam uma pessoa.
  tipo = 'falha_ferramenta';
  dadosResposta = { operacao: pendente.tipo || null };
}

// Reagendamento que esbarrou em horario ocupado: a consulta original continua
// de pe e ainda e o alvo. Perder o id aqui faria o proximo horario escolhido
// virar um agendamento novo, deixando o cliente com duas consultas.
const reagendarPreservado = (tipo === 'horario_ocupado' && pendente.tipo === 'reagendar')
  ? (pendente.consulta_id || null)
  : null;

return [{
  json: {
    sucesso,
    precisa_humano: precisaHumano,
    tipo_resposta: tipo,
    dados: dadosResposta,
    pendente_novo: null,
    // Junto com o id vai a consulta candidata: sem ela o turno seguinte perde o
    // serviço da consulta que está sendo remarcada e o fluxo volta a perguntar
    // "qual desses você quer?" no meio de uma remarcação já em andamento.
    estado_novo: {
      slots_oferecidos: [],
      consultas_candidatas: reagendarPreservado ? (ctx.estado.consultas_candidatas || []) : [],
      reagendar_consulta_id: reagendarPreservado,
    },
    log: Object.assign({}, decisao.log, {
      operacao: pendente.tipo || null,
      resultado: tipo,
      consulta_id: id,
      repetida: agendamento ? dados.repetida === true : null,
      codigo_erro: codigo || (temEnvelope ? null : 'sem_envelope'),
    }),
  },
}];

// Trata os agendamentos do proprio cliente. O filtro de empresa e de cliente e
// do servidor: a rota deriva a empresa da instancia e o cliente do telefone.
// Decide listar, pedir escolha, abrir cancelamento ou reagendamento.
// 30 min, nao 10: no WhatsApp o cliente le no onibus e responde depois.
// Alongar nao duplica agendamento - a API revalida na escrita e devolve
// CONFLITO_HORARIO, que vira `horario_ocupado` com reoferta.
const PENDENTE_MINUTOS = 30;
const OFFSET_MIN = -180;
const CHAVE_MAX = 120;
const MAX_LISTADAS = 3;
// Vocabulario da API: `cancelado` e `concluido` nao entram na lista de vivos.
const STATUS_ATIVOS = ['pendente', 'agendado', 'confirmado'];

const decisao = $('resolver e decidir').first().json;
const ctx = decisao.contexto;
const envelope = $input.first().json || {};

function numero(v) { const n = Number(v); return Number.isFinite(n) ? n : null; }
function normalizar(s) {
  return String(s === null || s === undefined ? '' : s).toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
    .replace(/[^a-z0-9\s/]/g, ' ').replace(/\s+/g, ' ').trim();
}

const temEnvelope = typeof envelope.ok === 'boolean';
const dados = (temEnvelope && envelope.ok === true && envelope.data) ? envelope.data : {};
const falhou = !temEnvelope || envelope.ok !== true;
const codigoErro = temEnvelope && envelope.error ? String(envelope.error.code || '') : 'sem_envelope';

const agoraMs = new Date(ctx.agora_iso).getTime();
const DIAS = ['domingo', 'segunda', 'terca', 'quarta', 'quinta', 'sexta', 'sabado'];

function partesLocais(iso) {
  const ms = new Date(iso).getTime() + OFFSET_MIN * 60000;
  const d = new Date(ms);
  return { dow: d.getUTCDay(), dia: d.getUTCDate(), hora: d.getUTCHours(), dias: Math.floor(ms / 86400000) };
}

const hojeLocal = partesLocais(ctx.agora_iso);
const conteudoNorm = normalizar(ctx.conteudo);

const consultas = (Array.isArray(dados.agendamentos) ? dados.agendamentos : [])
  .map((a) => {
    const procedimento = a.procedimento || {};
    const profissional = a.profissional || {};
    const duracao = numero(procedimento.duracao_minutos) || 60;
    const inicioMs = new Date(a.inicio).getTime();
    // `fim` vem da API; quando falta, a duracao do procedimento fecha o intervalo.
    const fimValido = a.fim && !Number.isNaN(new Date(a.fim).getTime());
    return {
      consulta_id: numero(a.id),
      inicio: a.inicio,
      fim: fimValido ? a.fim
        : (Number.isNaN(inicioMs) ? null : new Date(inicioMs + duracao * 60000).toISOString()),
      status: String(a.status || ''),
      servico_id: numero(procedimento.id),
      servico_nome: String(procedimento.nome || 'seu atendimento'),
      duracao_minutos: duracao,
      profissional_id: numero(profissional.id),
      profissional_nome: String(profissional.nome || ''),
    };
  })
  .filter((c) => c.consulta_id && c.inicio && !Number.isNaN(new Date(c.inicio).getTime()))
  // Corta pelo fim, nao pelo inicio: quem escreve "estou atrasado" durante o
  // proprio atendimento precisa continuar achando o horario dele na lista.
  .filter((c) => new Date(c.fim).getTime() > agoraMs)
  .filter((c) => !c.status || STATUS_ATIVOS.includes(c.status.toLowerCase()))
  .sort((a, b) => new Date(a.inicio) - new Date(b.inicio));

const listadas = consultas.slice(0, MAX_LISTADAS);
const textoPista = normalizar(`${decisao.interp.entities.appointment_hint || ''} ${decisao.interp.entities.date_text || ''} ${ctx.conteudo}`);
// "amanha" so e dia relativo quando nao faz parte de "depois de amanha".
const pediuAmanha = /\bamanha\b/.test(textoPista) && !/depois de amanha/.test(textoPista);

function pista(consulta) {
  if (!textoPista) return false;
  const p = partesLocais(consulta.inicio);
  if (/\bhoje\b/.test(textoPista) && p.dias === hojeLocal.dias) return true;
  if (pediuAmanha && p.dias === hojeLocal.dias + 1) return true;
  const hora = String(p.hora);
  return textoPista.includes(DIAS[p.dow])
    || new RegExp(`\\b${p.dia}\\b`).test(textoPista)
    || new RegExp(`\\b${hora}\\s?h`).test(textoPista)
    // "a das 10": hora nua, aceita so depois de artigo ou preposicao.
    || new RegExp(`\\b(?:as|das|de|a)\\s+${hora}\\b`).test(textoPista)
    || (consulta.servico_nome && textoPista.includes(normalizar(consulta.servico_nome)));
}

// Indice que o cliente digitou depois de "Qual deles?".
const candidatasExibidas = ((ctx.estado || {}).consultas_candidatas || []);
const temCandidatas = candidatasExibidas.length > 0;
// A lista que o cliente viu e a que o ordinal endereca. Sem lista aberta o
// ordinal cai para a busca deste turno, que e a unica ordem que existe.
const exibidas = temCandidatas ? candidatasExibidas : listadas;

function indiceOrdinal() {
  if (!conteudoNorm) return -1;
  const porOpcao = conteudoNorm.match(/\bopcao\s*([123])\b/);
  if (porOpcao) return Number(porOpcao[1]) - 1;
  const soNumero = conteudoNorm.match(/^(?:a|o|e|eh|quero|queria|pode ser|numero)?\s*([123])$/);
  if (soNumero) return Number(soNumero[1]) - 1;
  if (/\bprimeir/.test(conteudoNorm)) return 0;
  if (/\bterceir/.test(conteudoNorm)) return 2;
  // "segunda" e ordinal e dia da semana ao mesmo tempo. "A segunda" so quer
  // dizer "o item 2" quando existe uma lista numerada aberta; sem ela, o
  // cliente esta citando segunda-feira e quem resolve isso e a pista.
  // A preposicao desfaz o empate: "a DE segunda" e sempre o dia, nunca a
  // posicao — em portugues ninguem chama o segundo item de "o de segunda".
  if (temCandidatas
    && /\bsegund/.test(conteudoNorm)
    && !/\bsegunda feira\b/.test(conteudoNorm)
    && !/\bd[ae]\s+segund/.test(conteudoNorm)) return 1;
  return -1;
}

let motivoEscolha = null;

function resultado(tipo, dadosResposta, pendente, estado) {
  return [{
    json: {
      tipo_resposta: tipo,
      dados: dadosResposta || {},
      pendente_novo: pendente || null,
      estado_novo: Object.assign({ slots_oferecidos: [], consultas_candidatas: [], reagendar_consulta_id: null }, estado || {}),
      log: Object.assign({}, decisao.log, {
        tipo_resposta: tipo,
        consultas_encontradas: consultas.length,
        motivo_escolha: motivoEscolha,
        erro_ferramenta: falhou ? codigoErro : null,
      }),
    },
  }];
}

function novaPendenciaCancelar(consulta) {
  return {
    tipo: 'cancelar',
    acao_id: `${ctx.msg_id}:cancelar:${consulta.consulta_id}`.slice(0, CHAVE_MAX),
    consulta_id: consulta.consulta_id,
    inicio: consulta.inicio,
    servico_nome: consulta.servico_nome,
    profissional_nome: consulta.profissional_nome,
    criada_em: ctx.agora_iso,
    expira_em: new Date(agoraMs + PENDENTE_MINUTOS * 60000).toISOString(),
  };
}

function pedirEscolha() {
  return resultado(
    'escolher_consulta',
    { consultas: listadas, total: consultas.length, objetivo: decisao.objetivo || 'listar', motivo: motivoEscolha },
    null,
    { consultas_candidatas: listadas },
  );
}

// Consulta que falhou nao e agenda vazia: dizer "voce nao tem horario" seria
// afirmar algo que a ferramenta nao respondeu.
if (falhou) {
  return resultado('falha_temporaria', { operacao: 'consulta_de_agendamentos' }, null, {});
}

if (!consultas.length) {
  // O objetivo acompanha a resposta: quem pediu para cancelar nao pode ouvir
  // so uma oferta de marcar.
  return resultado('sem_consultas', { objetivo: decisao.objetivo || 'listar' }, null, {});
}

if (decisao.objetivo === 'listar') {
  // `total` diz quantas existem de verdade; a lista mostra no maximo tres.
  return resultado('lista_consultas', { consultas: listadas, total: consultas.length }, null, { consultas_candidatas: listadas });
}

// "as duas" / "todas": a intencao e clara, mas cancelar ou remarcar tudo de uma
// vez nunca sai de uma inferencia. Volta para escolha com a intencao no log.
// O verbo colado e o que separa o pedido da gentileza: "obrigado por todos os
// atendimentos, quero cancelar o de sexta" nomeia UMA consulta, e tratar como
// "todas" fazia o bot afirmar um pedido que o cliente nao fez.
if (consultas.length > 1
  && /\b(?:cancel\w*|remarc\w*|desmarc\w*|mud\w*|adi[ae]\w*|tir[ae]\w*)\s+(?:as duas|os dois|as tres|todas|todos|ambas|ambos)\b/
    .test(conteudoNorm)) {
  motivoEscolha = 'cliente_pediu_todas';
  return pedirEscolha();
}

const ordinal = indiceOrdinal();
const alvoExibido = ordinal >= 0 ? exibidas[ordinal] : null;
// Reconfere por id na busca deste turno: entre a lista e a resposta a agenda
// pode ter mudado, e ai o "2)" que o cliente leu seria outro horario.
const escolhaPorOrdem = alvoExibido
  ? (consultas.find((c) => c.consulta_id === alvoExibido.consulta_id) || null)
  : null;
if (alvoExibido && !escolhaPorOrdem) {
  // O horario escolhido saiu da agenda entre os dois turnos: repetir a lista e
  // mais seguro do que agir sobre o vizinho dele.
  motivoEscolha = 'escolha_indisponivel';
  return pedirEscolha();
}
// A pista concreta (dia, hora, servico) decide antes do ordinal: em "a de
// segunda" o cliente esta dizendo o dia, nao pedindo o segundo item da lista.
const porPista = consultas.filter(pista);
// Quando as duas leituras existem e apontam para consultas diferentes, nao ha
// como saber qual e a certa: "a segunda" logo depois de uma lista numerada pode
// ser o item 2) ou a consulta de segunda-feira. Cancelar e destrutivo, entao
// a duvida vira pergunta em vez de aposta.
if (porPista.length === 1 && escolhaPorOrdem
    && porPista[0].consulta_id !== escolhaPorOrdem.consulta_id) {
  motivoEscolha = 'dia_ou_posicao';
  return pedirEscolha();
}
const candidatas = consultas.length === 1 ? consultas
  : (porPista.length === 1 ? porPista : (escolhaPorOrdem ? [escolhaPorOrdem] : porPista));
if (candidatas.length !== 1) {
  motivoEscolha = candidatas.length ? 'pista_ambigua' : 'sem_pista';
  return pedirEscolha();
}

const escolhida = candidatas[0];
if (decisao.objetivo === 'cancelar') {
  return resultado('pedir_confirmacao_cancelamento', { consulta: escolhida }, novaPendenciaCancelar(escolhida), {});
}
// O servico e o profissional ja vieram da API nesta consulta: guardar a
// escolhida evita perguntar "qual servico?" de novo no proximo turno.
return resultado('pedir_nova_data', { consulta: escolhida }, null, {
  reagendar_consulta_id: escolhida.consulta_id,
  consultas_candidatas: [escolhida],
});

// Confirma a atualizacao cadastral so quando a API devolveu ok com os campos
// que ela realmente gravou. `campos_atualizados` vem do servidor, nao do pedido.
const ROTULOS = { nome: 'nome', email: 'e-mail', data_nascimento: 'data de nascimento', interesses: 'preferências' };

const decisao = $('resolver e decidir').first().json;
const envelope = $input.first().json || {};

const temEnvelope = typeof envelope.ok === 'boolean';
const dados = (temEnvelope && envelope.ok === true && envelope.data) ? envelope.data : {};
const ok = Boolean(dados.cliente);
const codigoErro = temEnvelope && envelope.error ? String(envelope.error.code || '') : 'sem_envelope';

const gravados = Array.isArray(dados.campos_atualizados) ? dados.campos_atualizados : [];
const campos = gravados.map((c) => ROTULOS[c] || c);

return [{
  json: {
    tipo_resposta: ok ? 'cadastro_atualizado' : 'falha_temporaria',
    dados: ok ? { campos } : { operacao: 'atualizacao_de_cadastro' },
    pendente_novo: null,
    estado_novo: { slots_oferecidos: [], consultas_candidatas: [], reagendar_consulta_id: null },
    log: Object.assign({}, decisao.log, {
      resultado: ok ? 'cadastro_atualizado' : 'falha',
      campos,
      erro_ferramenta: ok ? null : codigoErro,
    }),
  },
}];

// Mensagens operacionais deterministicas. Nenhuma IA e chamada para dizer que um
// horario foi marcado, alterado ou cancelado.
const OFFSET_MIN = -180;
const HISTORICO_MAX = 6;
const DIAS = ['domingo', 'segunda-feira', 'terça-feira', 'quarta-feira', 'quinta-feira', 'sexta-feira', 'sábado'];
// Vocabulario que so o sistema pode usar, e so depois de um efeito verificado.
// Efeito e o particípio sobre a agenda DESTE cliente, dito como fato. O
// substantivo de politica nao e efeito: "atendemos so com hora marcada" e a
// linha mais comum do campo "Sobre o negocio", e casar `marcad` solto matava a
// resposta certa.
const AFIRMA_EFEITO = /\b(?:esta|estava|ficou|foi|fica|deixei|seu hor[aá]rio|sua consulta|seu agendamento)\b[^.!?]{0,30}(?:agendad|confirmad|cancelad|remarcad|reservad|marcad)|(?:agendad|confirmad|cancelad|remarcad|reservad|marcad)\w*\s+(?:com sucesso|para voc[eê])/i;
// Numero que nao e dinheiro: hora, duracao, prazo, quantidade ("6 sessoes",
// "3 vezes", "2 andares"), porcentagem e data ("21/08"). Vale para achar o
// marcador e para varrer o resto da frase, senao "custa R$ 180 e dura 60
// minutos" viraria preco inventado.
const UNIDADE = '(?!\\s?(?:h\\b|:\\d|%|min|hora|dia|semana|m[eê]s|meses|ano|sess|vez|andar|por cento))(?![\\/-]\\d)';
// Dinheiro escrito pela IA, com ou sem cifrao: "R$ 180", "BRL 180", "180 reais",
// "180 pila", "de 180 por 99" (promocao) e numero logo depois de custa/fica/
// sai por/valor/preco. Todo achado precisa bater com o catalogo.
const VALOR_EM_REAIS = new RegExp(
  '(?:R\\$|BRL)\\s?\\d[\\d.,]*'
  + '|\\d[\\d.,]*\\s?(?:reais|real|contos?|pila|BRL)\\b'
  + '|\\bde\\s+\\d[\\d.,]*\\s+por\\s+\\d[\\d.,]*'
  + '|\\b(?:custa|fica|sai por|valor|pre[cç]o)\\b[\\s:]*'
